-- dnd5e-2024 / background (4)
insert into public.content (system_id, kind, name, slug, summary, description, data, parent_id) values
  ('dnd5e-2024', 'background', 'Acolyte', 'acolyte', null, 'You have spent your life in service to a temple, learning prayers, rites, and the tenets of your faith. The temple taught you to read and write.', '{"skill_proficiencies":["insight","religion"],"ability_score_options":{"abilities":["intelligence","wisdom","charisma"]},"origin_feat":"Magic Initiate (Cleric)","tool_proficiency":"Calligrapher''s Supplies"}'::jsonb, null),
  ('dnd5e-2024', 'background', 'Criminal', 'criminal', null, 'You are an experienced criminal with a history of breaking the law. You have spent a lot of time among other criminals and still have contacts within the criminal underworld.', '{"skill_proficiencies":["sleight-of-hand","stealth"],"ability_score_options":{"abilities":["dexterity","constitution","intelligence"]},"origin_feat":"Alert","tool_proficiency":"Thieves'' Tools"}'::jsonb, null),
  ('dnd5e-2024', 'background', 'Sage', 'sage', null, 'You spent years learning the lore of the multiverse. You scoured manuscripts, studied scrolls, and listened to the greatest experts on the subjects that interest you.', '{"skill_proficiencies":["arcana","history"],"ability_score_options":{"abilities":["constitution","intelligence","wisdom"]},"origin_feat":"Magic Initiate (Wizard)","tool_proficiency":"Calligrapher''s Supplies"}'::jsonb, null),
  ('dnd5e-2024', 'background', 'Soldier', 'soldier', null, 'War has been your life for as long as you can remember. You trained as a youth, studied the use of weapons and armor, learned basic survival techniques, and pledged yourself to a regiment.', '{"skill_proficiencies":["athletics","intimidation"],"ability_score_options":{"abilities":["strength","dexterity","constitution"]},"origin_feat":"Savage Attacker","tool_proficiency":"Gaming Set (choose one kind)"}'::jsonb, null)
on conflict do nothing;

