insert into public.content (system_id, kind, name, slug, summary, description, data, parent_id) values
  ('dnd5e-2024', 'class', 'Barbarian', 'barbarian', null, 'A fierce warrior of primal might who can enter a battle rage, channeling it into extraordinary attacks and resilience.', '{"hit_die":12,"primary_abilities":["strength","constitution"],"saving_throw_proficiencies":["strength","constitution"],"features":{"saving_throws":["Strength","Constitution"],"skill_choices":{"from":["Animal Handling","Athletics","Intimidation","Nature","Perception","Survival"],"count":2},"armor_training":["Light Armor","Medium Armor","Shields"],"level_features":{"1":["Rage","Unarmored Defense","Weapon Mastery"],"2":["Danger Sense","Reckless Attack"],"3":["Barbarian Subclass","Primal Knowledge"],"4":["Ability Score Improvement"],"5":["Extra Attack","Fast Movement"],"6":["Subclass Feature"],"7":["Feral Instinct","Instinctive Pounce"],"8":["Ability Score Improvement"],"9":["Brutal Strike"],"10":["Subclass Feature"],"11":["Relentless Rage"],"12":["Ability Score Improvement"],"13":["Improved Brutal Strike"],"14":["Subclass Feature"],"15":["Persistent Rage"],"16":["Ability Score Improvement"],"17":["Improved Brutal Strike"],"18":["Indomitable Might"],"19":["Epic Boon"],"20":["Primal Champion"]},"tool_proficiencies":[],"weapon_proficiencies":["Simple Weapons","Martial Weapons"],"starting_equipment_options":["Option A: Greataxe, 4 Handaxes, Explorer''s Pack, 15 GP","Option B: 75 GP"]}}'::jsonb, null),
  ('dnd5e-2024', 'class', 'Bard', 'bard', null, 'An inspiring magician whose power echoes the music of creation. Bards weave magic through words, music, and performance.', '{"hit_die":8,"primary_abilities":["charisma"],"saving_throw_proficiencies":["dexterity","charisma"],"features":{"saving_throws":["Dexterity","Charisma"],"skill_choices":{"from":["any"],"count":3},"armor_training":["Light Armor"],"level_features":{"1":["Bardic Inspiration","Spellcasting"],"2":["Expertise","Jack of All Trades"],"3":["Bard Subclass"],"4":["Ability Score Improvement"],"5":["Font of Inspiration"],"6":["Countercharm","Subclass Feature"],"7":["Expertise"],"8":["Ability Score Improvement"],"10":["Magical Secrets","Subclass Feature"],"12":["Ability Score Improvement"],"14":["Subclass Feature"],"16":["Ability Score Improvement"],"18":["Superior Inspiration","Subclass Feature"],"19":["Epic Boon"],"20":["Words of Creation"]},"tool_proficiencies":["Three Musical Instruments of your choice"],"weapon_proficiencies":["Simple Weapons","Hand Crossbows","Longswords","Rapiers","Shortswords"],"starting_equipment_options":["Option A: Leather Armor, 2 Daggers, Musical Instrument (your choice), Entertainer''s Pack, 19 GP","Option B: 75 GP"]}}'::jsonb, null),
  ('dnd5e-2024', 'class', 'Cleric', 'cleric', null, 'A priestly champion who wields divine magic in service of a higher power, healing allies and smiting foes.', '{"hit_die":8,"primary_abilities":["wisdom"],"saving_throw_proficiencies":["wisdom","charisma"],"features":{"saving_throws":["Wisdom","Charisma"],"skill_choices":{"from":["History","Insight","Medicine","Persuasion","Religion"],"count":2},"armor_training":["Light Armor","Medium Armor","Shields"],"level_features":{"1":["Spellcasting","Divine Order"],"2":["Channel Divinity"],"3":["Cleric Subclass"],"4":["Ability Score Improvement"],"5":["Sear Undead"],"6":["Subclass Feature"],"7":["Blessed Strikes"],"8":["Ability Score Improvement"],"10":["Divine Intervention"],"12":["Ability Score Improvement"],"14":["Improved Blessed Strikes"],"16":["Ability Score Improvement"],"18":["Subclass Feature"],"19":["Epic Boon"],"20":["Greater Divine Intervention"]},"tool_proficiencies":[],"weapon_proficiencies":["Simple Weapons"],"starting_equipment_options":["Option A: Chain Shirt, Shield, Mace, Holy Symbol, Priest''s Pack, 7 GP","Option B: 110 GP"]}}'::jsonb, null),
  ('dnd5e-2024', 'class', 'Druid', 'druid', null, 'A priest of the Old Faith, wielding the powers of nature — moonlight, plants, fire, and lightning — and adopting animal forms.', '{"hit_die":8,"primary_abilities":["wisdom"],"saving_throw_proficiencies":["intelligence","wisdom"],"features":{"saving_throws":["Intelligence","Wisdom"],"skill_choices":{"from":["Arcana","Animal Handling","Insight","Medicine","Nature","Perception","Religion","Survival"],"count":2},"armor_training":["Light Armor","Medium Armor","Shields"],"level_features":{"1":["Spellcasting","Druidic","Primal Order"],"2":["Wild Shape","Wild Companion"],"3":["Druid Subclass"],"4":["Ability Score Improvement","Wild Shape Improvement"],"5":["Wild Resurgence"],"6":["Subclass Feature"],"7":["Elemental Fury"],"8":["Ability Score Improvement"],"10":["Subclass Feature"],"12":["Ability Score Improvement"],"14":["Subclass Feature"],"15":["Improved Elemental Fury"],"16":["Ability Score Improvement"],"18":["Beast Spells","Subclass Feature"],"19":["Epic Boon"],"20":["Archdruid"]},"tool_proficiencies":["Herbalism Kit"],"weapon_proficiencies":["Simple Weapons","Scimitars"],"starting_equipment_options":["Option A: Leather Armor, Shield, Sickle, Druidic Focus (Quarterstaff), Explorer''s Pack, Herbalism Kit, 9 GP","Option B: 50 GP"]}}'::jsonb, null),
  ('dnd5e-2024', 'class', 'Fighter', 'fighter', null, 'A master of martial combat, skilled with a variety of weapons and armor, capable of remarkable feats on the battlefield.', '{"hit_die":10,"primary_abilities":["strength","dexterity"],"saving_throw_proficiencies":["strength","constitution"],"features":{"saving_throws":["Strength","Constitution"],"skill_choices":{"from":["Acrobatics","Animal Handling","Athletics","History","Insight","Intimidation","Persuasion","Perception","Survival"],"count":2},"armor_training":["Light Armor","Medium Armor","Heavy Armor","Shields"],"level_features":{"1":["Fighting Style","Second Wind","Weapon Mastery"],"2":["Action Surge","Tactical Mind"],"3":["Fighter Subclass"],"4":["Ability Score Improvement"],"5":["Extra Attack","Tactical Shift"],"6":["Ability Score Improvement"],"7":["Subclass Feature"],"8":["Ability Score Improvement"],"9":["Indomitable","Tactical Master"],"10":["Subclass Feature"],"11":["Two Extra Attacks"],"12":["Ability Score Improvement"],"13":["Studied Attacks"],"14":["Ability Score Improvement"],"15":["Subclass Feature"],"16":["Ability Score Improvement"],"18":["Subclass Feature"],"19":["Epic Boon"],"20":["Three Extra Attacks"]},"tool_proficiencies":[],"weapon_proficiencies":["Simple Weapons","Martial Weapons"],"starting_equipment_options":["Option A: Chain Mail, Greatsword, Flail, 8 Javelins, Dungeoneer''s Pack, 4 GP","Option B: Leather Armor, Scimitar, Shortsword, Longbow, 20 Arrows, Quiver, Dungeoneer''s Pack, 11 GP","Option C: 155 GP"]}}'::jsonb, null),
  ('dnd5e-2024', 'class', 'Monk', 'monk', null, 'A master of martial arts, harnessing the power of the body and ki to perform amazing feats.', '{"hit_die":8,"primary_abilities":["dexterity","wisdom"],"saving_throw_proficiencies":["strength","dexterity"],"features":{"saving_throws":["Strength","Dexterity"],"skill_choices":{"from":["Acrobatics","Athletics","History","Insight","Religion","Stealth"],"count":2},"armor_training":[],"level_features":{"1":["Martial Arts","Unarmored Defense"],"2":["Monk''s Focus","Unarmored Movement","Uncanny Metabolism"],"3":["Deflect Attacks","Monk Subclass"],"4":["Ability Score Improvement","Slow Fall"],"5":["Extra Attack","Stunning Strike"],"6":["Empowered Strikes"],"7":["Evasion"],"8":["Ability Score Improvement"],"9":["Acrobatic Movement"],"10":["Heightened Focus","Self-Restoration"],"12":["Ability Score Improvement"],"13":["Deflect Energy"],"14":["Disciplined Survivor"],"15":["Perfect Focus"],"16":["Ability Score Improvement"],"18":["Superior Defense"],"19":["Epic Boon"],"20":["Body and Mind"]},"tool_proficiencies":["Artisan''s Tools or Musical Instrument (your choice)"],"weapon_proficiencies":["Simple Weapons","Martial Weapons with the Light property"],"starting_equipment_options":["Option A: Spear, 5 Daggers, Artisan''s Tools or Musical Instrument, Dungeoneer''s Pack, 9 GP","Option B: 65 GP"]}}'::jsonb, null),
  ('dnd5e-2024', 'class', 'Paladin', 'paladin', null, 'A holy warrior bound to a sacred oath, wielding divine magic and martial prowess to protect the innocent.', '{"hit_die":10,"primary_abilities":["strength","charisma"],"saving_throw_proficiencies":["wisdom","charisma"],"features":{"saving_throws":["Wisdom","Charisma"],"skill_choices":{"from":["Athletics","Insight","Intimidation","Medicine","Persuasion","Religion"],"count":2},"armor_training":["Light Armor","Medium Armor","Heavy Armor","Shields"],"level_features":{"1":["Lay On Hands","Spellcasting","Weapon Mastery"],"2":["Fighting Style","Paladin''s Smite"],"3":["Channel Divinity","Paladin Subclass"],"4":["Ability Score Improvement"],"5":["Extra Attack","Faithful Steed"],"6":["Aura of Protection"],"8":["Ability Score Improvement"],"10":["Aura of Courage"],"11":["Radiant Strikes"],"12":["Ability Score Improvement"],"14":["Restoring Touch"],"16":["Ability Score Improvement"],"18":["Aura Expansion"],"19":["Epic Boon"],"20":["Subclass Feature"]},"tool_proficiencies":[],"weapon_proficiencies":["Simple Weapons","Martial Weapons"],"starting_equipment_options":["Option A: Chain Mail, Shield, Longsword, 6 Javelins, Holy Symbol, Priest''s Pack, 9 GP","Option B: 150 GP"]}}'::jsonb, null),
  ('dnd5e-2024', 'class', 'Ranger', 'ranger', null, 'A warrior who combats threats on the edges of civilization, expert in tracking, nature, and ranged combat.', '{"hit_die":10,"primary_abilities":["dexterity","wisdom"],"saving_throw_proficiencies":["strength","dexterity"],"features":{"saving_throws":["Strength","Dexterity"],"skill_choices":{"from":["Animal Handling","Athletics","Insight","Investigation","Nature","Perception","Stealth","Survival"],"count":3},"armor_training":["Light Armor","Medium Armor","Shields"],"level_features":{"1":["Spellcasting","Favored Enemy","Weapon Mastery"],"2":["Deft Explorer","Fighting Style"],"3":["Ranger Subclass"],"4":["Ability Score Improvement"],"5":["Extra Attack"],"6":["Roving"],"8":["Ability Score Improvement"],"9":["Expertise"],"10":["Tireless"],"12":["Ability Score Improvement"],"13":["Relentless Hunter"],"14":["Nature''s Veil"],"16":["Ability Score Improvement"],"17":["Precise Hunter"],"18":["Feral Senses"],"19":["Epic Boon"],"20":["Foe Slayer"]},"tool_proficiencies":[],"weapon_proficiencies":["Simple Weapons","Martial Weapons"],"starting_equipment_options":["Option A: Leather Armor, Scimitar, Shortsword, Longbow, 20 Arrows, Quiver, Druidic Focus (Quarterstaff), Explorer''s Pack, 7 GP","Option B: 150 GP"]}}'::jsonb, null),
  ('dnd5e-2024', 'class', 'Rogue', 'rogue', null, 'A scoundrel who uses stealth, trickery, and precise strikes to overcome obstacles and defeat foes.', '{"hit_die":8,"primary_abilities":["dexterity"],"saving_throw_proficiencies":["dexterity","intelligence"],"features":{"saving_throws":["Dexterity","Intelligence"],"skill_choices":{"from":["Acrobatics","Athletics","Deception","Insight","Intimidation","Investigation","Perception","Persuasion","Sleight of Hand","Stealth"],"count":4},"armor_training":["Light Armor"],"level_features":{"1":["Expertise","Sneak Attack","Thieves'' Cant","Weapon Mastery"],"2":["Cunning Action"],"3":["Rogue Subclass","Steady Aim"],"4":["Ability Score Improvement"],"5":["Cunning Strike","Uncanny Dodge"],"7":["Evasion","Reliable Talent"],"8":["Ability Score Improvement"],"10":["Ability Score Improvement"],"11":["Improved Cunning Strike"],"12":["Ability Score Improvement"],"14":["Devious Strikes"],"15":["Slippery Mind"],"16":["Ability Score Improvement"],"18":["Elusive"],"19":["Epic Boon"],"20":["Stroke of Luck"]},"tool_proficiencies":["Thieves'' Tools"],"weapon_proficiencies":["Simple Weapons","Hand Crossbows","Longswords","Rapiers","Shortswords"],"starting_equipment_options":["Option A: Leather Armor, 2 Daggers, Shortsword, Shortbow, 20 Arrows, Quiver, Thieves'' Tools, Burglar''s Pack, 8 GP","Option B: 100 GP"]}}'::jsonb, null),
  ('dnd5e-2024', 'class', 'Sorcerer', 'sorcerer', null, 'A spellcaster who draws on inherent magic from a gift or bloodline, bending spells with Metamagic.', '{"hit_die":6,"primary_abilities":["charisma"],"saving_throw_proficiencies":["constitution","charisma"],"features":{"saving_throws":["Constitution","Charisma"],"skill_choices":{"from":["Arcana","Deception","Insight","Intimidation","Persuasion","Religion"],"count":2},"armor_training":[],"level_features":{"1":["Spellcasting","Innate Sorcery"],"2":["Font of Magic","Metamagic"],"3":["Sorcerer Subclass"],"4":["Ability Score Improvement"],"5":["Sorcerous Restoration"],"7":["Sorcery Incarnate"],"8":["Ability Score Improvement"],"12":["Ability Score Improvement"],"16":["Ability Score Improvement"],"19":["Epic Boon"],"20":["Arcane Apotheosis"]},"tool_proficiencies":[],"weapon_proficiencies":["Simple Weapons"],"starting_equipment_options":["Option A: Spear, 2 Daggers, Arcane Focus (crystal), Dungeoneer''s Pack, 28 GP","Option B: 50 GP"]}}'::jsonb, null),
  ('dnd5e-2024', 'class', 'Warlock', 'warlock', null, 'A wielder of magic derived from a bargain with an extraplanar entity, channeling eldritch power through Pact Magic.', '{"hit_die":8,"primary_abilities":["charisma"],"saving_throw_proficiencies":["wisdom","charisma"],"features":{"saving_throws":["Wisdom","Charisma"],"skill_choices":{"from":["Arcana","Deception","History","Intimidation","Investigation","Nature","Religion"],"count":2},"armor_training":["Light Armor"],"level_features":{"1":["Eldritch Invocations","Pact Magic"],"2":["Magical Cunning"],"3":["Warlock Subclass"],"4":["Ability Score Improvement"],"8":["Ability Score Improvement"],"9":["Contact Patron"],"11":["Mystic Arcanum (Level 6 Spell)"],"12":["Ability Score Improvement"],"13":["Mystic Arcanum (Level 7 Spell)"],"15":["Mystic Arcanum (Level 8 Spell)"],"16":["Ability Score Improvement"],"17":["Mystic Arcanum (Level 9 Spell)"],"19":["Epic Boon"],"20":["Eldritch Master"]},"tool_proficiencies":[],"weapon_proficiencies":["Simple Weapons"],"starting_equipment_options":["Option A: Leather Armor, Sickle, 2 Daggers, Arcane Focus (orb), Book (occult lore), Scholar''s Pack, 15 GP","Option B: 100 GP"]}}'::jsonb, null),
  ('dnd5e-2024', 'class', 'Wizard', 'wizard', null, 'A scholarly magic-user capable of manipulating the structures of reality, preparing spells from a spellbook.', '{"hit_die":6,"primary_abilities":["intelligence"],"saving_throw_proficiencies":["intelligence","wisdom"],"features":{"saving_throws":["Intelligence","Wisdom"],"skill_choices":{"from":["Arcana","History","Insight","Investigation","Medicine","Religion"],"count":3},"armor_training":[],"level_features":{"1":["Spellcasting","Ritual Adept","Arcane Recovery"],"2":["Scholar"],"3":["Wizard Subclass"],"4":["Ability Score Improvement"],"5":["Memorize Spell"],"8":["Ability Score Improvement"],"12":["Ability Score Improvement"],"16":["Ability Score Improvement"],"18":["Spell Mastery"],"19":["Epic Boon"],"20":["Signature Spells"]},"tool_proficiencies":[],"weapon_proficiencies":["Simple Weapons"],"starting_equipment_options":["Option A: 2 Daggers, Arcane Focus (Quarterstaff), Spellbook, Scholar''s Pack, 5 GP","Option B: 55 GP"]}}'::jsonb, null)
