-- dnd5e-2024 / feat (17)
insert into public.content (system_id, kind, name, slug, summary, description, data, parent_id) values
  ('dnd5e-2024', 'feat', 'Ability Score Improvement', 'ability-score-improvement', null, null, '{"prerequisites":{"level":4},"benefits":"Increase one ability score by 2, or two ability scores by 1 each. No score can exceed 20. Repeatable.","ability_score_bonuses":{"amount":2,"options":"any","or_split":true}}'::jsonb, null),
  ('dnd5e-2024', 'feat', 'Alert', 'alert', null, null, '{"prerequisites":{},"benefits":"Initiative Proficiency: When you roll Initiative, add your Proficiency Bonus to the roll. Initiative Swap: Immediately after rolling Initiative, you can swap your Initiative with one willing ally in the same combat (neither can have Incapacitated).","ability_score_bonuses":{}}'::jsonb, null),
  ('dnd5e-2024', 'feat', 'Archery', 'archery', null, null, '{"prerequisites":{"feature":"Fighting Style"},"benefits":"You gain a +2 bonus to attack rolls you make with Ranged weapons.","ability_score_bonuses":{}}'::jsonb, null),
  ('dnd5e-2024', 'feat', 'Boon of Combat Prowess', 'boon-of-combat-prowess', null, null, '{"prerequisites":{"level":19},"benefits":"Ability Score Increase: +1 to one ability score (max 30). Peerless Aim: When you miss with an attack roll, you can hit instead. Once per turn.","ability_score_bonuses":{"max":30,"amount":1,"options":"any"}}'::jsonb, null),
  ('dnd5e-2024', 'feat', 'Boon of Dimensional Travel', 'boon-of-dimensional-travel', null, null, '{"prerequisites":{"level":19},"benefits":"Ability Score Increase: +1 to one ability score (max 30). Blink Steps: Immediately after you take the Attack action or Magic action, teleport up to 30 feet to an unoccupied space you can see.","ability_score_bonuses":{"max":30,"amount":1,"options":"any"}}'::jsonb, null),
  ('dnd5e-2024', 'feat', 'Boon of Fate', 'boon-of-fate', null, null, '{"prerequisites":{"level":19},"benefits":"Ability Score Increase: +1 to one ability score (max 30). Improve Fate: When you or a creature within 60 feet succeeds or fails a D20 Test, roll 2d4 and apply the total as a bonus or penalty to the d20 roll. Once per Initiative or Short/Long Rest.","ability_score_bonuses":{"max":30,"amount":1,"options":"any"}}'::jsonb, null),
  ('dnd5e-2024', 'feat', 'Boon of Irresistible Offense', 'boon-of-irresistible-offense', null, null, '{"prerequisites":{"level":19},"benefits":"Ability Score Increase: +1 to Strength or Dexterity (max 30). Overcome Defenses: Your Bludgeoning, Piercing, and Slashing damage always ignores Resistance. Overwhelming Strike: On a nat-20 attack roll, deal bonus damage equal to the boosted ability score (same type as the attack).","ability_score_bonuses":{"max":30,"amount":1,"options":["strength","dexterity"]}}'::jsonb, null),
  ('dnd5e-2024', 'feat', 'Boon of Spell Recall', 'boon-of-spell-recall', null, null, '{"prerequisites":{"level":19},"benefits":"Prerequisite: Spellcasting class feature. Ability Score Increase: +1 to Intelligence, Wisdom, or Charisma (max 30). Free Casting: When you cast a spell with a level 1–4 slot, roll 1d4. If the result equals the slot level, the slot is not expended.","ability_score_bonuses":{"max":30,"amount":1,"options":["intelligence","wisdom","charisma"]}}'::jsonb, null),
  ('dnd5e-2024', 'feat', 'Boon of the Night Spirit', 'boon-of-the-night-spirit', null, null, '{"prerequisites":{"level":19},"benefits":"Ability Score Increase: +1 to one ability score (max 30). Merge with Shadows: While in Dim Light or Darkness, gain the Invisible condition as a Bonus Action (ends when you take any action, bonus action, or reaction). Shadowy Form: While in Dim Light or Darkness, Resistance to all damage except Psychic and Radiant.","ability_score_bonuses":{"max":30,"amount":1,"options":"any"}}'::jsonb, null),
  ('dnd5e-2024', 'feat', 'Boon of Truesight', 'boon-of-truesight', null, null, '{"prerequisites":{"level":19},"benefits":"Ability Score Increase: +1 to one ability score (max 30). Truesight: You have Truesight with a range of 60 feet.","ability_score_bonuses":{"max":30,"amount":1,"options":"any"}}'::jsonb, null),
  ('dnd5e-2024', 'feat', 'Defense', 'defense', null, null, '{"prerequisites":{"feature":"Fighting Style"},"benefits":"While wearing Light, Medium, or Heavy armor, you gain a +1 bonus to Armor Class.","ability_score_bonuses":{}}'::jsonb, null),
  ('dnd5e-2024', 'feat', 'Grappler', 'grappler', null, null, '{"prerequisites":{"level":4},"benefits":"Prerequisite: Strength or Dexterity 13+. Ability Score Increase: +1 to Strength or Dexterity (max 20). Punch and Grab: When you hit with an Unarmed Strike as part of the Attack action, you can use both the Damage and Grapple option (once per turn). Attack Advantage: You have Advantage on attack rolls against a creature you have Grappled. Fast Wrestler: No extra movement to move a Grappled creature of your size or smaller.","ability_score_bonuses":{"amount":1,"options":["strength","dexterity"]}}'::jsonb, null),
  ('dnd5e-2024', 'feat', 'Great Weapon Fighting', 'great-weapon-fighting', null, null, '{"prerequisites":{"feature":"Fighting Style"},"benefits":"When you roll damage for a Melee weapon attack with a Two-Handed or Versatile weapon held in two hands, treat any 1 or 2 on a damage die as a 3.","ability_score_bonuses":{}}'::jsonb, null),
  ('dnd5e-2024', 'feat', 'Magic Initiate', 'magic-initiate', null, null, '{"prerequisites":{},"benefits":"Choose Cleric, Druid, or Wizard list when taken. Repeatable once per list. Two Cantrips: Learn 2 cantrips from the chosen spell list. Level 1 Spell: Learn 1 level-1 spell from the same list; always prepared, cast once without a slot per Long Rest, or with spell slots. Spell Change: Replace one chosen spell on each level-up.","ability_score_bonuses":{}}'::jsonb, null),
  ('dnd5e-2024', 'feat', 'Savage Attacker', 'savage-attacker', null, null, '{"prerequisites":{},"benefits":"Once per turn when you hit a target with a weapon, roll the weapon''s damage dice twice and use either roll.","ability_score_bonuses":{}}'::jsonb, null),
  ('dnd5e-2024', 'feat', 'Skilled', 'skilled', null, null, '{"prerequisites":{},"benefits":"Gain proficiency in any combination of three skills or tools of your choice. Repeatable.","ability_score_bonuses":{}}'::jsonb, null),
  ('dnd5e-2024', 'feat', 'Two-Weapon Fighting', 'two-weapon-fighting', null, null, '{"prerequisites":{"feature":"Fighting Style"},"benefits":"When you make an extra attack using a weapon with the Light property, you can add your ability modifier to the damage of that attack even if you haven''t already added it.","ability_score_bonuses":{}}'::jsonb, null)
on conflict do nothing;

