-- dnd5e-2024 / magic_item (273)
insert into public.content (system_id, kind, name, slug, summary, description, data, parent_id) values
  ('dnd5e-2024', 'magic_item', 'Adamantine Armor', 'adamantine-armor', null, 'This suit of armor is reinforced with adamantine, one of the hardest substances in existence. While you''re wearing it, any Critical Hit against you becomes a normal hit.', '{"item_type":"Armor","rarity":"Uncommon","requires_attunement":false,"attunement_condition":null,"properties":{"applies_to":"Any Medium or Heavy armor except Hide"}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Ammunition, +1', 'ammunition-1', null, 'You have a +1 bonus to attack rolls and damage rolls made with this piece of magic ammunition. Once it hits a target, the ammunition is no longer magical.', '{"item_type":"Weapon","rarity":"Uncommon","requires_attunement":false,"attunement_condition":null,"properties":{"bonus":1}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Ammunition, +2', 'ammunition-2', null, 'You have a +2 bonus to attack rolls and damage rolls made with this piece of magic ammunition. Once it hits a target, the ammunition is no longer magical.', '{"item_type":"Weapon","rarity":"Rare","requires_attunement":false,"attunement_condition":null,"properties":{"bonus":2}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Ammunition, +3', 'ammunition-3', null, 'You have a +3 bonus to attack rolls and damage rolls made with this piece of magic ammunition. Once it hits a target, the ammunition is no longer magical.', '{"item_type":"Weapon","rarity":"Very Rare","requires_attunement":false,"attunement_condition":null,"properties":{"bonus":3}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Ammunition of Slaying', 'ammunition-of-slaying', null, 'This magic ammunition is meant to slay creatures of a particular type. If a creature of that type takes damage from the ammunition, the creature makes a DC 17 Constitution saving throw, taking an extra 6d10 Force damage on a failed save or half as much extra damage on a successful one. After dealing its extra damage to a creature, the ammunition becomes nonmagical.', '{"item_type":"Weapon","rarity":"Very Rare","requires_attunement":false,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Amulet of Health', 'amulet-of-health', null, 'Your Constitution score is 19 while you wear this amulet. It has no effect if your Constitution is already 19 or higher.', '{"item_type":"Wondrous Item","rarity":"Rare","requires_attunement":true,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Amulet of Proof against Detection and Location', 'amulet-of-proof-against-detection-and-location', null, 'While wearing this amulet, you can''t be targeted by Divination spells or perceived through magical scrying sensors unless you allow it.', '{"item_type":"Wondrous Item","rarity":"Uncommon","requires_attunement":true,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Amulet of the Planes', 'amulet-of-the-planes', null, 'While wearing this amulet, you can take a Magic action to name a location that you are familiar with on another plane of existence. Then make a DC 15 Intelligence (Arcana) check. On a successful check, you cast Plane Shift. On a failed check, you and each creature and object within 15 feet of you travel to a random destination.', '{"item_type":"Wondrous Item","rarity":"Very Rare","requires_attunement":true,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Animated Shield', 'animated-shield', null, 'While holding this Shield, you can take a Bonus Action to cause it to animate. The Shield leaps into the air and hovers in your space to protect you as if you were wielding it, leaving your hands free. The Shield remains animate for 1 minute, until you take a Bonus Action to end this effect, or until you die or have the Incapacitated condition.', '{"item_type":"Armor","rarity":"Very Rare","requires_attunement":true,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Apparatus of the Crab', 'apparatus-of-the-crab', null, 'This item first appears to be a sealed iron barrel weighing 500 pounds. The barrel has a hidden catch. Releasing it unlocks a hatch at one end, allowing two Medium or smaller creatures to crawl inside. Ten levers allow the apparatus to transform into a giant lobster. The Apparatus of the Crab is a Large object: AC 20; HP 200; Speed 30 ft., Swim 30 ft.; Immunity to Poison and Psychic damage. It can submerge to 900 feet depth.', '{"item_type":"Wondrous Item","rarity":"Legendary","requires_attunement":false,"attunement_condition":null,"properties":{"ac":20,"hp":200}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Armor, +1', 'armor-1', null, 'You have a +1 bonus to Armor Class while wearing this armor (any Light, Medium, or Heavy).', '{"item_type":"Armor","rarity":"Rare","requires_attunement":false,"attunement_condition":null,"properties":{"bonus":1}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Armor, +2', 'armor-2', null, 'You have a +2 bonus to Armor Class while wearing this armor (any Light, Medium, or Heavy).', '{"item_type":"Armor","rarity":"Very Rare","requires_attunement":false,"attunement_condition":null,"properties":{"bonus":2}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Armor, +3', 'armor-3', null, 'You have a +3 bonus to Armor Class while wearing this armor (any Light, Medium, or Heavy).', '{"item_type":"Armor","rarity":"Legendary","requires_attunement":false,"attunement_condition":null,"properties":{"bonus":3}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Armor of Invulnerability', 'armor-of-invulnerability', null, 'You have Resistance to Bludgeoning, Piercing, and Slashing damage while you wear this armor. Metal Shell. You can take a Magic action to give yourself Immunity to Bludgeoning, Piercing, and Slashing damage for 10 minutes or until you are no longer wearing the armor. Once this property is used, it can''t be used again until the next dawn.', '{"item_type":"Armor","rarity":"Legendary","requires_attunement":true,"attunement_condition":null,"properties":{"applies_to":"Plate Armor"}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Armor of Resistance', 'armor-of-resistance', null, 'You have Resistance to one type of damage while you wear this armor. The GM chooses the type or determines it randomly.', '{"item_type":"Armor","rarity":"Rare","requires_attunement":true,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Armor of Vulnerability', 'armor-of-vulnerability', null, 'While wearing this armor, you have Resistance to one of the following damage types: Bludgeoning, Piercing, or Slashing. Curse. This armor is cursed. While cursed, you have Vulnerability to two of the three damage types associated with the armor.', '{"item_type":"Armor","rarity":"Rare","requires_attunement":true,"attunement_condition":null,"properties":{"cursed":true}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Arrow-Catching Shield', 'arrow-catching-shield', null, 'You gain a +2 bonus to Armor Class against ranged attack rolls while you wield this Shield. This bonus is in addition to the Shield''s normal bonus to AC. Whenever an attacker makes a ranged attack roll against a target within 5 feet of you, you can take a Reaction to become the target of the attack instead.', '{"item_type":"Armor","rarity":"Rare","requires_attunement":true,"attunement_condition":null,"properties":{"bonus_vs_ranged":2}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Bag of Beans', 'bag-of-beans', null, 'This heavy cloth bag contains 3d4 dry beans when found. If you dump one or more beans out of the bag, they explode in a 10-foot-radius Sphere centered on them, dealing 5d4 Force damage (DC 15 Dexterity save for half). If you remove a bean from the bag, plant it in dirt or sand, and then water it, the bean disappears and produces a random magical effect 1 minute later.', '{"item_type":"Wondrous Item","rarity":"Rare","requires_attunement":false,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Bag of Devouring', 'bag-of-devouring', null, 'This bag resembles a Bag of Holding but is a feeding orifice for a gigantic extradimensional creature. Animal or vegetable matter placed wholly in the bag is devoured and lost forever. When part of a living creature is placed in the bag, there is a 50 percent chance that the creature is pulled inside the bag. Any creature that starts its turn inside the bag is devoured, its body destroyed.', '{"item_type":"Wondrous Item","rarity":"Very Rare","requires_attunement":false,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Bag of Holding', 'bag-of-holding', null, 'This bag has an interior space considerably larger than its outside dimensions—roughly 2 feet square and 4 feet deep on the inside. The bag can hold up to 500 pounds, not exceeding a volume of 64 cubic feet. The bag weighs 5 pounds, regardless of its contents.', '{"item_type":"Wondrous Item","rarity":"Uncommon","requires_attunement":false,"attunement_condition":null,"properties":{"capacity_lbs":500,"capacity_cubic_ft":64}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Bag of Tricks (Gray)', 'bag-of-tricks-gray', null, 'This bag made from gray cloth appears empty. Reaching inside reveals a small, fuzzy object. You can take a Magic action to pull the fuzzy object from the bag and throw it up to 20 feet. When the object lands, it transforms into a random creature (Gray table). The creature is Friendly to you and vanishes at the next dawn or when it drops to 0 Hit Points. Once three fuzzy objects have been pulled from the bag, the bag can''t be used again until the next dawn.', '{"item_type":"Wondrous Item","rarity":"Uncommon","requires_attunement":false,"attunement_condition":null,"properties":{"color":"gray"}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Bag of Tricks (Rust)', 'bag-of-tricks-rust', null, 'This bag made from rust cloth appears empty. Reaching inside reveals a small, fuzzy object. You can take a Magic action to pull the fuzzy object from the bag and throw it up to 20 feet. When the object lands, it transforms into a random creature (Rust table). The creature is Friendly to you and vanishes at the next dawn or when it drops to 0 Hit Points.', '{"item_type":"Wondrous Item","rarity":"Very Rare","requires_attunement":false,"attunement_condition":null,"properties":{"color":"rust"}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Bag of Tricks (Tan)', 'bag-of-tricks-tan', null, 'This bag made from tan cloth appears empty. Reaching inside reveals a small, fuzzy object. You can take a Magic action to pull the fuzzy object from the bag and throw it up to 20 feet. When the object lands, it transforms into a random creature (Tan table). The creature is Friendly to you and vanishes at the next dawn or when it drops to 0 Hit Points.', '{"item_type":"Wondrous Item","rarity":"Uncommon","requires_attunement":false,"attunement_condition":null,"properties":{"color":"tan"}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Bead of Force', 'bead-of-force', null, 'This small black sphere measures 3/4 of an inch in diameter and weighs an ounce. You can take a Magic action to throw the bead up to 60 feet. The bead explodes in a 10-foot-radius Sphere on impact and is destroyed. Each creature in the Sphere must succeed on a DC 15 Dexterity saving throw or take 5d4 Force damage. A sphere of transparent force then encloses the area for 1 minute.', '{"item_type":"Wondrous Item","rarity":"Rare","requires_attunement":false,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Bead of Nourishment', 'bead-of-nourishment', null, 'This flavorless, gelatinous bead dissolves on your tongue and provides as much nourishment as 1 day of Rations.', '{"item_type":"Wondrous Item","rarity":"Common","requires_attunement":false,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Belt of Dwarvenkind', 'belt-of-dwarvenkind', null, 'While wearing this belt, you gain the following benefits: you know Dwarvish; you have Advantage on Charisma (Persuasion) checks made to interact with dwarves and duergar; your Constitution increases by 2, to a maximum of 20. If you aren''t a dwarf or duergar, you also gain Darkvision with a range of 60 feet and Resistance to Poison damage.', '{"item_type":"Wondrous Item","rarity":"Rare","requires_attunement":true,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Belt of Giant Strength', 'belt-of-giant-strength', null, 'While wearing this belt, your Strength changes to a score granted by the belt. The type of giant determines the score: Hill (21, Rare), Frost/Stone (23, Very Rare), Fire (25, Very Rare), Cloud (27, Legendary), Storm (29, Legendary). The item has no effect if your Strength without the belt equals or exceeds the belt''s score.', '{"item_type":"Wondrous Item","rarity":"Varies","requires_attunement":true,"attunement_condition":null,"properties":{"varies_by_type":true}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Berserker Axe', 'berserker-axe', null, 'You gain a +1 bonus to attack rolls and damage rolls made with this magic weapon. In addition, while you are attuned to this weapon, your Hit Point maximum increases by 1 for each level you have attained. Curse. While cursed, you are unwilling to part with the weapon. Whenever another creature damages you while the weapon is in your possession, you must succeed on a DC 15 Wisdom saving throw or go berserk.', '{"item_type":"Weapon","rarity":"Rare","requires_attunement":true,"attunement_condition":null,"properties":{"bonus":1,"cursed":true}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Boots of Elvenkind', 'boots-of-elvenkind', null, 'While you wear these boots, your steps make no sound, regardless of the surface you are moving across. You also have Advantage on Dexterity (Stealth) checks.', '{"item_type":"Wondrous Item","rarity":"Uncommon","requires_attunement":false,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Boots of Levitation', 'boots-of-levitation', null, 'While you wear these boots, you can cast Levitate on yourself.', '{"item_type":"Wondrous Item","rarity":"Rare","requires_attunement":true,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Boots of Speed', 'boots-of-speed', null, 'While you wear these boots, you can take a Bonus Action to click the boots'' heels together. If you do, the boots double your Speed, and any creature that makes an Opportunity Attack against you has Disadvantage on the attack roll. When you''ve used the boots'' property for a total of 10 minutes, the magic ceases to function until you finish a Long Rest.', '{"item_type":"Wondrous Item","rarity":"Rare","requires_attunement":true,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Boots of Striding and Springing', 'boots-of-striding-and-springing', null, 'While you wear these boots, your Speed becomes 30 feet unless your Speed is higher, and your Speed isn''t reduced by carrying weight in excess of your carrying capacity or wearing Heavy Armor. Once on each of your turns, you can jump up to 30 feet by spending only 10 feet of movement.', '{"item_type":"Wondrous Item","rarity":"Uncommon","requires_attunement":true,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Boots of the Winterlands', 'boots-of-the-winterlands', null, 'These furred boots are snug and feel warm. While wearing them, you have Resistance to Cold damage, can tolerate temperatures of 0 degrees Fahrenheit or lower without any additional protection, and you ignore Difficult Terrain created by ice or snow.', '{"item_type":"Wondrous Item","rarity":"Uncommon","requires_attunement":true,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Bowl of Commanding Water Elementals', 'bowl-of-commanding-water-elementals', null, 'While this bowl is filled with water and you are within 5 feet of it, you can take a Magic action to summon a Water Elemental. The elemental obeys your commands and takes its turn immediately after you on your Initiative count. The elemental disappears after 1 hour, when it dies, or when you dismiss it as a Bonus Action. The bowl can''t be used this way again until the next dawn.', '{"item_type":"Wondrous Item","rarity":"Rare","requires_attunement":false,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Bracers of Archery', 'bracers-of-archery', null, 'While wearing these bracers, you have proficiency with the Longbow and Shortbow, and you gain a +2 bonus to damage rolls made with such weapons.', '{"item_type":"Wondrous Item","rarity":"Uncommon","requires_attunement":true,"attunement_condition":null,"properties":{"damage_bonus":2}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Bracers of Defense', 'bracers-of-defense', null, 'While wearing these bracers, you gain a +2 bonus to Armor Class if you are wearing no armor and using no Shield.', '{"item_type":"Wondrous Item","rarity":"Rare","requires_attunement":true,"attunement_condition":null,"properties":{"ac_bonus":2}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Brazier of Commanding Fire Elementals', 'brazier-of-commanding-fire-elementals', null, 'While you are within 5 feet of this brazier, you can take a Magic action to summon a Fire Elemental. The elemental obeys your commands. The elemental disappears after 1 hour, when it dies, or when you dismiss it as a Bonus Action. The brazier can''t be used this way again until the next dawn.', '{"item_type":"Wondrous Item","rarity":"Rare","requires_attunement":false,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Brooch of Shielding', 'brooch-of-shielding', null, 'While wearing this brooch, you have Resistance to Force damage, and you have Immunity to damage from the Magic Missile spell.', '{"item_type":"Wondrous Item","rarity":"Uncommon","requires_attunement":true,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Broom of Flying', 'broom-of-flying', null, 'This wooden broom functions like a mundane broom until you stand astride it and take a Magic action to make it hover beneath you. It has a Fly Speed of 50 feet. It can carry up to 400 pounds, but its Fly Speed becomes 30 feet while carrying over 200 pounds. As a Magic action, you can send the broom to travel alone to a destination within 1 mile of you if you name the location and are familiar with it.', '{"item_type":"Wondrous Item","rarity":"Uncommon","requires_attunement":true,"attunement_condition":null,"properties":{"fly_speed":50}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Candle of Invocation', 'candle-of-invocation', null, 'This candle''s magic is activated when the candle is lit, which requires a Magic action. After burning for 4 hours, the candle is destroyed. While lit, the candle sheds Dim Light in a 30-foot radius. While you are within that light, you have Advantage on D20 Tests. In addition, a Cleric or Druid in the light can cast level 1 spells they have prepared without expending spell slots.', '{"item_type":"Wondrous Item","rarity":"Very Rare","requires_attunement":true,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Cape of the Mountebank', 'cape-of-the-mountebank', null, 'This cape smells faintly of brimstone. While wearing it, you can use it to cast Dimension Door as a Magic action. This property can''t be used again until the next dawn. When you teleport with that spell, you leave behind a cloud of smoke.', '{"item_type":"Wondrous Item","rarity":"Rare","requires_attunement":false,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Carpet of Flying', 'carpet-of-flying', null, 'You can make this carpet hover and fly by taking a Magic action and using the carpet''s command word. It moves according to your directions if you are within 30 feet of it. Four sizes of Carpet of Flying exist, ranging from 3 ft. x 5 ft. (80 ft. Fly Speed) to 6 ft. x 9 ft. (30 ft. Fly Speed). A carpet can carry up to twice its normal weight capacity, but its Fly Speed is halved if it carries more than its normal capacity.', '{"item_type":"Wondrous Item","rarity":"Very Rare","requires_attunement":false,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Censer of Controlling Air Elementals', 'censer-of-controlling-air-elementals', null, 'While gently swinging this censer, you can take a Magic action to summon an Air Elemental. The elemental obeys your commands. The elemental disappears after 1 hour, when it dies, or when you dismiss it as a Bonus Action. The censer can''t be used this way again until the next dawn.', '{"item_type":"Wondrous Item","rarity":"Rare","requires_attunement":false,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Chime of Opening', 'chime-of-opening', null, 'This hollow metal tube measures about 1 foot long and weighs 1 pound. As a Magic action, you can strike the chime to cast Knock. The spell''s customary knocking sound is replaced by the clear, ringing tone of the chime, which is audible out to 300 feet. The chime can be used 10 times. After the tenth time, it cracks and becomes useless.', '{"item_type":"Wondrous Item","rarity":"Rare","requires_attunement":false,"attunement_condition":null,"properties":{"charges":10}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Circlet of Blasting', 'circlet-of-blasting', null, 'While wearing this circlet, you can cast Scorching Ray with it (+5 to hit). The circlet can''t cast this spell again until the next dawn.', '{"item_type":"Wondrous Item","rarity":"Uncommon","requires_attunement":false,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Cloak of Arachnida', 'cloak-of-arachnida', null, 'This fine garment is made of black silk interwoven with faint, silvery threads. While wearing it, you gain Resistance to Poison damage, a Climb Speed equal to your Speed, the ability to move through webs as Difficult Terrain, and you can cast Web (save DC 13) once per dawn.', '{"item_type":"Wondrous Item","rarity":"Very Rare","requires_attunement":true,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Cloak of Displacement', 'cloak-of-displacement', null, 'While you wear this cloak, it magically projects an illusion that makes you appear to be standing in a place near your actual location, causing any creature to have Disadvantage on attack rolls against you. If you take damage, the property ceases to function until the start of your next turn. This property is suppressed while your Speed is 0.', '{"item_type":"Wondrous Item","rarity":"Rare","requires_attunement":true,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Cloak of Elvenkind', 'cloak-of-elvenkind', null, 'While you wear this cloak, Wisdom (Perception) checks made to perceive you have Disadvantage, and you have Advantage on Dexterity (Stealth) checks.', '{"item_type":"Wondrous Item","rarity":"Uncommon","requires_attunement":true,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Cloak of Invisibility', 'cloak-of-invisibility', null, 'This cloak has 3 charges and regains 1d3 expended charges daily at dawn. While wearing the cloak, you can take a Magic action to pull its hood over your head and expend 1 charge to give yourself the Invisible condition for 1 hour.', '{"item_type":"Wondrous Item","rarity":"Legendary","requires_attunement":true,"attunement_condition":null,"properties":{"charges":3}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Cloak of Protection', 'cloak-of-protection', null, 'You gain a +1 bonus to Armor Class and saving throws while you wear this cloak.', '{"item_type":"Wondrous Item","rarity":"Uncommon","requires_attunement":true,"attunement_condition":null,"properties":{"ac_bonus":1,"save_bonus":1}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Cloak of the Bat', 'cloak-of-the-bat', null, 'While wearing this cloak, you have Advantage on Dexterity (Stealth) checks. In an area of Dim Light or Darkness, you can grip the edges of the cloak and use it to gain a Fly Speed of 40 feet. While wearing the cloak in an area of Dim Light or Darkness, you can cast Polymorph on yourself, shape-shifting into a Bat. The cloak can''t be used this way again until the next dawn.', '{"item_type":"Wondrous Item","rarity":"Rare","requires_attunement":true,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Cloak of the Manta Ray', 'cloak-of-the-manta-ray', null, 'While wearing this cloak, you can breathe underwater, and you have a Swim Speed of 60 feet.', '{"item_type":"Wondrous Item","rarity":"Uncommon","requires_attunement":true,"attunement_condition":null,"properties":{"swim_speed":60}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Crystal Ball', 'crystal-ball', null, 'While touching this crystal orb, you can cast Scrying (save DC 17) with it.', '{"item_type":"Wondrous Item","rarity":"Very Rare","requires_attunement":true,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Crystal Ball of Mind Reading', 'crystal-ball-of-mind-reading', null, 'While touching this crystal orb, you can cast Scrying (save DC 17) with it. In addition, you can cast Detect Thoughts (save DC 17) targeting creatures you can see within 30 feet of the spell''s sensor. You don''t need to concentrate on this Detect Thoughts spell.', '{"item_type":"Wondrous Item","rarity":"Legendary","requires_attunement":true,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Crystal Ball of Telepathy', 'crystal-ball-of-telepathy', null, 'While touching this crystal orb, you can cast Scrying (save DC 17) with it. In addition, you can communicate telepathically with creatures you can see within 30 feet of the spell''s sensor. You can also cast Suggestion (save DC 17) through the sensor on one of those creatures.', '{"item_type":"Wondrous Item","rarity":"Legendary","requires_attunement":true,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Crystal Ball of True Seeing', 'crystal-ball-of-true-seeing', null, 'While touching this crystal orb, you can cast Scrying (save DC 17) with it. In addition, you have Truesight with a range of 120 feet centered on the spell''s sensor.', '{"item_type":"Wondrous Item","rarity":"Legendary","requires_attunement":true,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Cube of Force', 'cube-of-force', null, 'This cube is about an inch across. Each face has a distinct marking on it. You can press one of those faces, expend the number of charges required, and cast the spell associated with it (save DC 17). The cube starts with 10 charges, and it regains 1d6 expended charges daily at dawn.', '{"item_type":"Wondrous Item","rarity":"Rare","requires_attunement":true,"attunement_condition":null,"properties":{"charges":10}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Cubic Gate', 'cubic-gate', null, 'This cube is 3 inches across and radiates palpable magical energy. The six sides of the cube are each keyed to a different plane of existence, one of which is the Material Plane. The cube has 3 charges and regains 1d3 expended charges daily at dawn. As a Magic action, you can expend 1 charge to cast Gate or Plane Shift using the cube.', '{"item_type":"Wondrous Item","rarity":"Legendary","requires_attunement":false,"attunement_condition":null,"properties":{"charges":3}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Dagger of Venom', 'dagger-of-venom', null, 'You gain a +1 bonus to attack rolls and damage rolls made with this magic weapon. You can take a Bonus Action to magically coat the blade with poison. The poison remains for 1 minute or until an attack using this weapon hits a creature. That creature must succeed on a DC 15 Constitution saving throw or take 2d10 Poison damage and have the Poisoned condition for 1 minute.', '{"item_type":"Weapon","rarity":"Rare","requires_attunement":false,"attunement_condition":null,"properties":{"bonus":1}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Dancing Sword', 'dancing-sword', null, 'You can take a Bonus Action to toss this magic weapon into the air. When you do so, the weapon begins to hover, flies up to 30 feet, and attacks one creature of your choice within 5 feet of itself. The weapon uses your attack roll and adds your ability modifier to damage rolls. After the hovering weapon attacks for the fourth time, it flies back to you.', '{"item_type":"Weapon","rarity":"Very Rare","requires_attunement":true,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Decanter of Endless Water', 'decanter-of-endless-water', null, 'This stoppered flask sloshes when shaken, as if it contains water. You can take a Magic action to remove the stopper and issue one of three command words to produce water: Splash (1 gallon), Fountain (5 gallons), or Geyser (30 gallons in a 30-foot Line, DC 13 Strength save or take 1d4 Bludgeoning damage and fall Prone).', '{"item_type":"Wondrous Item","rarity":"Uncommon","requires_attunement":false,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Deck of Illusions', 'deck-of-illusions', null, 'This box contains a set of cards. A full deck has 34 cards: 32 depicting specific creatures and two with a mirrored surface. You can take a Magic action to draw a card at random and throw it to the ground. An illusion of a creature forms over the thrown card and remains until dispelled. The illusory creature can''t do harm. Any physical interaction with it reveals it to be false.', '{"item_type":"Wondrous Item","rarity":"Uncommon","requires_attunement":false,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Defender', 'defender', null, 'You gain a +3 bonus to attack rolls and damage rolls made with this magic weapon. The first time you attack with the weapon on each of your turns, you can transfer some or all of the weapon''s bonus to your Armor Class instead. The adjusted bonuses remain in effect until the start of your next turn.', '{"item_type":"Weapon","rarity":"Legendary","requires_attunement":true,"attunement_condition":null,"properties":{"bonus":3}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Demon Armor', 'demon-armor', null, 'While wearing this armor, you gain a +1 bonus to Armor Class, and you know Abyssal. The armor''s clawed gauntlets allow your Unarmed Strikes to deal 1d8 Slashing damage, and you gain a +1 bonus to the attack and damage rolls of your Unarmed Strikes. Curse. Once you don this cursed armor, you can''t doff it unless targeted by a Remove Curse spell.', '{"item_type":"Armor","rarity":"Very Rare","requires_attunement":true,"attunement_condition":null,"properties":{"bonus":1,"cursed":true}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Dimensional Shackles', 'dimensional-shackles', null, 'You can take a Utilize action to place these shackles on a creature that has the Incapacitated condition. The shackles prevent a creature bound by them from using any method of extradimensional movement, including teleportation or travel to a different plane of existence. Once every 30 days, the bound creature can make a DC 30 Strength (Athletics) check to break free.', '{"item_type":"Wondrous Item","rarity":"Rare","requires_attunement":false,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Dragon Orb', 'dragon-orb', null, 'An orb is an etched crystal globe about 10 inches in diameter. While attuned to an orb, you can take a Magic action to peer into the orb''s depths (DC 15 Charisma saving throw or the orb imposes the Charmed condition on you). The orb has 7 charges and can cast various spells including Cure Wounds, Daylight, Death Ward, Detect Magic, and Scrying. You can also use it to Call Dragons within 40 miles.', '{"item_type":"Wondrous Item","rarity":"Artifact","requires_attunement":true,"attunement_condition":null,"properties":{"charges":7}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Dragon Scale Mail', 'dragon-scale-mail', null, 'Made of the scales of one kind of dragon. While wearing this armor, you gain a +1 bonus to Armor Class, you have Advantage on saving throws against the breath weapons of Dragons, and you have Resistance to one damage type determined by the kind of dragon that provided the scales. Additionally, you can focus your senses to discern the distance and direction to the closest dragon of the same type within 30 miles.', '{"item_type":"Armor","rarity":"Very Rare","requires_attunement":true,"attunement_condition":null,"properties":{"bonus":1}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Dragon Slayer', 'dragon-slayer', null, 'You gain a +1 bonus to attack rolls and damage rolls made with this magic weapon. The weapon deals an extra 3d6 damage of the weapon''s type if the target is a Dragon.', '{"item_type":"Weapon","rarity":"Rare","requires_attunement":false,"attunement_condition":null,"properties":{"bonus":1}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Dust of Disappearance', 'dust-of-disappearance', null, 'This powder resembles fine sand. There is enough of it for one use. When you take a Utilize action to throw the dust into the air, you and each creature and object within a 10-foot Emanation have the Invisible condition for 2d4 minutes. Immediately after an affected creature makes an attack roll, deals damage, or casts a spell, the Invisible condition ends for that creature.', '{"item_type":"Wondrous Item","rarity":"Uncommon","requires_attunement":false,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Dust of Dryness', 'dust-of-dryness', null, 'This small packet contains 1d6 + 4 pinches of dust. As a Utilize action, you can sprinkle a pinch of the dust over water, turning up to a 15-foot Cube of water into one marble-sized pellet. You can also sprinkle a pinch on a water-based Elemental within 5 feet of yourself, which must make a DC 13 Constitution saving throw, taking 10d6 Necrotic damage on a failure.', '{"item_type":"Wondrous Item","rarity":"Uncommon","requires_attunement":false,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Dust of Sneezing and Choking', 'dust-of-sneezing-and-choking', null, 'Found in a small container, this powder resembles Dust of Disappearance, and Identify reveals it to be such. As a Utilize action, you can throw the dust into the air, forcing yourself and every creature in a 30-foot Emanation to make a DC 15 Constitution saving throw. On a failed save, a creature begins sneezing uncontrollably; it has the Incapacitated condition and is suffocating.', '{"item_type":"Wondrous Item","rarity":"Uncommon","requires_attunement":false,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Dwarven Plate', 'dwarven-plate', null, 'While wearing this armor, you gain a +2 bonus to Armor Class. In addition, if an effect moves you against your will along the ground, you can take a Reaction to reduce the distance you are moved by up to 10 feet.', '{"item_type":"Armor","rarity":"Very Rare","requires_attunement":false,"attunement_condition":null,"properties":{"bonus":2}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Dwarven Thrower', 'dwarven-thrower', null, 'You gain a +3 bonus to attack rolls and damage rolls made with this magic weapon. It has the Thrown property with a normal range of 20 feet and a long range of 60 feet. When you hit with a ranged attack using this weapon, it deals an extra 1d8 Force damage, or an extra 2d8 Force damage if the target is a Giant. Immediately after hitting or missing, the weapon flies back to your hand.', '{"item_type":"Weapon","rarity":"Very Rare","requires_attunement":true,"attunement_condition":"by a Dwarf or a Creature Attuned to a Belt of Dwarvenkind","properties":{"bonus":3}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Efficient Quiver', 'efficient-quiver', null, 'Each of the quiver''s three compartments connects to an extradimensional space that allows the quiver to hold numerous items while never weighing more than 2 pounds. The shortest compartment can hold up to 60 Arrows or Bolts. The mid-size compartment holds up to 18 Javelins or similar objects. The longest compartment holds up to 6 long objects, such as bows, Quarterstaffs, or Spears.', '{"item_type":"Wondrous Item","rarity":"Uncommon","requires_attunement":false,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Efreeti Bottle', 'efreeti-bottle', null, 'When you take a Magic action to remove the stopper of this painted brass bottle, a cloud of thick smoke flows out of it. At the end of your turn, an Efreeti appears in an unoccupied space within 30 feet of you. The first time the bottle is opened, roll 1d10 to determine the efreeti''s reaction: on a 1, it attacks you; on 2-9, it obeys your commands for 1 hour; on a 10, it grants one Wish.', '{"item_type":"Wondrous Item","rarity":"Very Rare","requires_attunement":false,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Elemental Gem', 'elemental-gem', null, 'This gem contains a mote of elemental energy. When you take a Utilize action to break the gem, an elemental is summoned and the gem ceases to be magical. The type of gem determines the elemental: Blue sapphire (Air Elemental), Emerald (Water Elemental), Red corundum (Fire Elemental), Yellow diamond (Earth Elemental).', '{"item_type":"Wondrous Item","rarity":"Uncommon","requires_attunement":false,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Elixir of Health', 'elixir-of-health', null, 'When you drink this potion, you are cured of all magical contagions. In addition, the following conditions end on you: Blinded, Deafened, Paralyzed, and Poisoned. The clear, red liquid has tiny bubbles of light in it.', '{"item_type":"Potion","rarity":"Rare","requires_attunement":false,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Elven Chain', 'elven-chain', null, 'You gain a +1 bonus to Armor Class while you wear this armor. You are considered trained with this armor even if you lack training with Medium or Heavy armor.', '{"item_type":"Armor","rarity":"Rare","requires_attunement":false,"attunement_condition":null,"properties":{"bonus":1}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Energy Bow', 'energy-bow', null, 'You gain a +1 bonus to attack rolls and damage rolls made with this magic weapon, which has no string. Each time you pull your arm back in a firing motion, a magical arrow made of golden energy appears nocked and ready to fire. An arrow produced by this weapon deals Force damage. The bow has additional properties: Arrow of Restraint (DC 15 Strength save or Restrained), Arrow of Transport (teleports a target), and Energy Ladder (creates a magical ladder).', '{"item_type":"Weapon","rarity":"Very Rare","requires_attunement":true,"attunement_condition":null,"properties":{"bonus":1}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Eversmoking Bottle', 'eversmoking-bottle', null, 'As a Magic action, you can open or close this bottle. Opening the bottle causes thick smoke to billow out, forming a cloud that fills a 60-foot Emanation originating from the bottle. The area within the smoke is Heavily Obscured. Each minute the bottle remains open, the Emanation increases by 10 feet to a maximum size of 120 feet.', '{"item_type":"Wondrous Item","rarity":"Uncommon","requires_attunement":false,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Eyes of Charming', 'eyes-of-charming', null, 'These crystal lenses fit over the eyes. They have 3 charges. While wearing them, you can expend 1 or more charges to cast Charm Person (save DC 13). The lenses regain all expended charges daily at dawn.', '{"item_type":"Wondrous Item","rarity":"Uncommon","requires_attunement":true,"attunement_condition":null,"properties":{"charges":3}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Eyes of Minute Seeing', 'eyes-of-minute-seeing', null, 'These crystal lenses fit over the eyes. While wearing them, your vision improves significantly out to a range of 1 foot, granting you Darkvision within that range and Advantage on Intelligence (Investigation) checks made to examine something within that range.', '{"item_type":"Wondrous Item","rarity":"Uncommon","requires_attunement":false,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Eyes of the Eagle', 'eyes-of-the-eagle', null, 'These crystal lenses fit over the eyes. While wearing them, you have Advantage on Wisdom (Perception) checks that rely on sight. In conditions of clear visibility, you can make out details of even extremely distant creatures and objects as small as 2 feet across.', '{"item_type":"Wondrous Item","rarity":"Uncommon","requires_attunement":false,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Feather Token', 'feather-token', null, 'This object looks like a feather. Different types of feather tokens exist, each with a different single-use effect. Types include: Anchor (Uncommon), Bird (Rare), Fan (Uncommon), Swan Boat (Rare), Tree (Uncommon), and Whip (Rare).', '{"item_type":"Wondrous Item","rarity":"Varies","requires_attunement":false,"attunement_condition":null,"properties":{"varies_by_type":true}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Figurine of Wondrous Power', 'figurine-of-wondrous-power', null, 'A Figurine of Wondrous Power is a statuette small enough to fit in a pocket. If you take a Magic action to throw the figurine to a point on the ground within 60 feet, the figurine becomes a living creature. Types include: Bronze Griffon (Rare), Ebony Fly (Rare), Golden Lions (Rare), Ivory Goats (Rare), Marble Elephant (Rare), Obsidian Steed (Very Rare), Onyx Dog (Rare), Serpentine Owl (Rare), Silver Raven (Uncommon).', '{"item_type":"Wondrous Item","rarity":"Varies","requires_attunement":false,"attunement_condition":null,"properties":{"varies_by_type":true}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Flame Tongue', 'flame-tongue', null, 'While holding this magic weapon, you can take a Bonus Action and use a command word to cause flames to engulf the damage-dealing part of the weapon. These flames shed Bright Light in a 40-foot radius and Dim Light for an additional 40 feet. While the weapon is ablaze, it deals an extra 2d6 Fire damage on a hit.', '{"item_type":"Weapon","rarity":"Rare","requires_attunement":true,"attunement_condition":null,"properties":{"extra_damage":"2d6 fire"}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Folding Boat', 'folding-boat', null, 'This object appears as a wooden box that measures 12 inches long, 6 inches wide, and 6 inches deep. It weighs 4 pounds and floats. It has three command words, each requiring a Magic action: the first unfolds it into a Rowboat, the second into a Keelboat, and the third folds it back into a box.', '{"item_type":"Wondrous Item","rarity":"Rare","requires_attunement":false,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Frost Brand', 'frost-brand', null, 'When you hit with an attack roll using this magic weapon, the target takes an extra 1d6 Cold damage. While you hold the weapon, you have Resistance to Fire damage. In freezing temperatures, the weapon sheds Bright Light in a 10-foot radius. When you draw this weapon, you can extinguish all nonmagical flames within 30 feet of yourself (once per hour).', '{"item_type":"Weapon","rarity":"Very Rare","requires_attunement":true,"attunement_condition":null,"properties":{"extra_damage":"1d6 cold"}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Gauntlets of Ogre Power', 'gauntlets-of-ogre-power', null, 'Your Strength is 19 while you wear these gauntlets. They have no effect on you if your Strength is 19 or higher without them.', '{"item_type":"Wondrous Item","rarity":"Uncommon","requires_attunement":true,"attunement_condition":null,"properties":{"strength":19}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Gem of Brightness', 'gem-of-brightness', null, 'This prism has 50 charges. While you are holding it, you can take a Magic action and use one of three command words: the first sheds Bright Light in a 30-foot radius (no charge); the second fires a blinding beam at one creature (DC 15 Constitution save or Blinded, 1 charge); the third causes a 30-foot Cone of intense light (5 charges). When all charges are expended, the gem becomes a nonmagical jewel worth 50 GP.', '{"item_type":"Wondrous Item","rarity":"Uncommon","requires_attunement":false,"attunement_condition":null,"properties":{"charges":50}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Gem of Seeing', 'gem-of-seeing', null, 'This gem has 3 charges. As a Magic action, you can expend 1 charge. For the next 10 minutes, you have Truesight out to 120 feet when you peer through the gem. The gem regains 1d3 expended charges daily at dawn.', '{"item_type":"Wondrous Item","rarity":"Rare","requires_attunement":true,"attunement_condition":null,"properties":{"charges":3}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Giant Slayer', 'giant-slayer', null, 'You gain a +1 bonus to attack rolls and damage rolls made with this magic weapon. When you hit a Giant with this weapon, the Giant takes an extra 2d6 damage of the weapon''s type and must succeed on a DC 15 Strength saving throw or have the Prone condition.', '{"item_type":"Weapon","rarity":"Rare","requires_attunement":false,"attunement_condition":null,"properties":{"bonus":1}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Glamoured Studded Leather', 'glamoured-studded-leather', null, 'While wearing this armor, you gain a +1 bonus to Armor Class. You can also take a Bonus Action to cause the armor to assume the appearance of a normal set of clothing or some other kind of armor. The illusory appearance lasts until you use this property again or doff the armor.', '{"item_type":"Armor","rarity":"Rare","requires_attunement":false,"attunement_condition":null,"properties":{"bonus":1}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Gloves of Missile Snaring', 'gloves-of-missile-snaring', null, 'If you''re hit by an attack roll made with a Ranged or Thrown weapon while wearing these gloves, you can take a Reaction to reduce the damage by 1d10 plus your Dexterity modifier if you have a free hand. If you reduce the damage to 0, you can catch the ammunition or weapon if it is small enough for you to hold in that hand.', '{"item_type":"Wondrous Item","rarity":"Uncommon","requires_attunement":true,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Gloves of Swimming and Climbing', 'gloves-of-swimming-and-climbing', null, 'While wearing these gloves, you have a Climb Speed and a Swim Speed equal to your Speed, and you gain a +5 bonus to Strength (Athletics) checks made to climb or swim.', '{"item_type":"Wondrous Item","rarity":"Uncommon","requires_attunement":true,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Gloves of Thievery', 'gloves-of-thievery', null, 'These gloves are imperceptible while worn. While wearing them, you gain a +5 bonus to Dexterity (Sleight of Hand) checks.', '{"item_type":"Wondrous Item","rarity":"Uncommon","requires_attunement":false,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Goggles of Night', 'goggles-of-night', null, 'While wearing these dark lenses, you have Darkvision out to 60 feet. If you already have Darkvision, wearing the goggles increases its range by 60 feet.', '{"item_type":"Wondrous Item","rarity":"Uncommon","requires_attunement":false,"attunement_condition":null,"properties":{"darkvision":60}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Hammer of Thunderbolts', 'hammer-of-thunderbolts', null, 'You gain a +1 bonus to attack rolls and damage rolls made with this magic weapon. The weapon has 5 charges. You can expend 1 charge to make a ranged attack hurling it (20 ft. normal range, 60 ft. long). If the attack hits, it unleashes a thunderclap audible out to 300 feet, and the target and every creature within 30 feet must succeed on a DC 17 Constitution saving throw or have the Stunned condition. When attuned with a Belt of Giant Strength or Gauntlets of Ogre Power, you gain additional benefits including potentially slaying Giants on a 20.', '{"item_type":"Weapon","rarity":"Legendary","requires_attunement":true,"attunement_condition":null,"properties":{"bonus":1,"charges":5}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Handy Haversack', 'handy-haversack', null, 'This backpack has a central pouch and two side pouches, each of which is an extradimensional space. Each side pouch can hold up to 200 pounds, not exceeding a volume of 25 cubic feet. The central pouch can hold up to 500 pounds, not exceeding a volume of 64 cubic feet. The haversack always weighs 5 pounds, regardless of its contents.', '{"item_type":"Wondrous Item","rarity":"Rare","requires_attunement":false,"attunement_condition":null,"properties":{"capacity_lbs":500,"capacity_cubic_ft":64}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Hat of Disguise', 'hat-of-disguise', null, 'While wearing this hat, you can cast the Disguise Self spell. The spell ends if the hat is removed.', '{"item_type":"Wondrous Item","rarity":"Uncommon","requires_attunement":true,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Hat of Many Spells', 'hat-of-many-spells', null, 'This pointed hat functions as a Spellcasting Focus for Wizard spells. While holding the hat, you can try to cast a level 1+ spell you don''t know from the Wizard spell list (Intelligence (Arcana) check DC 10 + spell level). On a success, you cast the spell. On a failure, a random effect occurs instead.', '{"item_type":"Wondrous Item","rarity":"Very Rare","requires_attunement":true,"attunement_condition":"by a Wizard","properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Headband of Intellect', 'headband-of-intellect', null, 'Your Intelligence is 19 while you wear this headband. It has no effect on you if your Intelligence is 19 or higher without it.', '{"item_type":"Wondrous Item","rarity":"Uncommon","requires_attunement":true,"attunement_condition":null,"properties":{"intelligence":19}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Helm of Brilliance', 'helm-of-brilliance', null, 'This helm is set with 1d10 diamonds, 2d10 rubies, 3d10 fire opals, and 4d10 opals. You gain benefits while wearing the helm: diamonds emit an Emanation that damages Undead; fire opals allow a weapon to burst into flames dealing extra 1d6 Fire damage; rubies grant Resistance to Fire damage; and gems allow casting of Daylight, Fireball, Prismatic Spray, or Wall of Fire.', '{"item_type":"Wondrous Item","rarity":"Very Rare","requires_attunement":true,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Helm of Comprehending Languages', 'helm-of-comprehending-languages', null, 'While wearing this helm, you can cast Comprehend Languages from it.', '{"item_type":"Wondrous Item","rarity":"Uncommon","requires_attunement":false,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Helm of Telepathy', 'helm-of-telepathy', null, 'While wearing this helm, you have telepathy with a range of 30 feet, and you can cast Detect Thoughts or Suggestion (save DC 13) from the helm. Once either spell is cast from the helm, that spell can''t be cast from it again until the next dawn.', '{"item_type":"Wondrous Item","rarity":"Uncommon","requires_attunement":true,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Helm of Teleportation', 'helm-of-teleportation', null, 'This helm has 3 charges. While wearing it, you can expend 1 charge to cast Teleport from it. The helm regains 1d3 expended charges daily at dawn.', '{"item_type":"Wondrous Item","rarity":"Rare","requires_attunement":true,"attunement_condition":null,"properties":{"charges":3}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Holy Avenger', 'holy-avenger', null, 'You gain a +3 bonus to attack rolls and damage rolls made with this magic weapon. When you hit a Fiend or an Undead with it, that creature takes an extra 2d10 Radiant damage. While you hold the drawn weapon, it creates a 10-foot Emanation. You and all creatures Friendly to you in the Emanation have Advantage on saving throws against spells and other magical effects.', '{"item_type":"Weapon","rarity":"Legendary","requires_attunement":true,"attunement_condition":"by a Paladin","properties":{"bonus":3,"extra_damage_vs_fiend_undead":"2d10 radiant"}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Horn of Blasting', 'horn-of-blasting', null, 'You can take a Magic action to blow the horn, which emits a thunderous blast in a 30-foot Cone audible out to 600 feet. Each creature in the Cone makes a DC 15 Constitution saving throw. On a failed save, a creature takes 5d8 Thunder damage and has the Deafened condition for 1 minute. Each use of the horn''s magic has a 20 percent chance of causing the horn to explode, dealing 10d6 Force damage to the user.', '{"item_type":"Wondrous Item","rarity":"Rare","requires_attunement":false,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Horn of Valhalla', 'horn-of-valhalla', null, 'You can take a Magic action to blow this horn. In response, warrior spirits from the plane of Ysgard appear within 60 feet of you and remain for 1 hour. Four types exist: Silver (2 spirits, Rare), Brass (3 spirits, Rare), Bronze (4 spirits, Very Rare), Iron (5 spirits, Legendary). If you blow the horn without meeting its requirement, the summoned spirits attack you.', '{"item_type":"Wondrous Item","rarity":"Varies","requires_attunement":false,"attunement_condition":null,"properties":{"varies_by_type":true}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Horseshoes of a Zephyr', 'horseshoes-of-a-zephyr', null, 'These horseshoes come in a set of four. While all four shoes are affixed to the hooves of a horse or similar creature, they allow the creature to move normally while floating 4 inches above a surface. The creature can cross or stand above nonsolid or unstable surfaces, leaves no tracks, ignores Difficult Terrain, and can travel for up to 12 hours a day without gaining Exhaustion from extended travel.', '{"item_type":"Wondrous Item","rarity":"Very Rare","requires_attunement":false,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Horseshoes of Speed', 'horseshoes-of-speed', null, 'These horseshoes come in a set of four. While all four horseshoes are attached to the same creature, its Speed is increased by 30 feet.', '{"item_type":"Wondrous Item","rarity":"Rare","requires_attunement":false,"attunement_condition":null,"properties":{"speed_bonus":30}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Immovable Rod', 'immovable-rod', null, 'This iron rod has a button on one end. You can take a Utilize action to press the button, which causes the rod to become magically fixed in place. Until you or another creature takes a Utilize action to push the button again, the rod doesn''t move, even if it defies gravity. The rod can hold up to 8,000 pounds of weight.', '{"item_type":"Rod","rarity":"Uncommon","requires_attunement":false,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Instant Fortress', 'instant-fortress', null, 'As a Magic action, you can place this 1-inch adamantine statuette on the ground and, using a command word, cause it to grow rapidly into a square adamantine tower, 20 feet on a side and 30 feet high. The tower has arrow slits on all sides and a battlement atop it. Only a Wish spell can repair the tower.', '{"item_type":"Wondrous Item","rarity":"Rare","requires_attunement":true,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Ioun Stone', 'ioun-stone', null, 'When you take a Magic action to toss an Ioun Stone into the air, the stone orbits your head at a distance of 1d3 feet, conferring its benefit to you. Types include: Absorption (Very Rare), Agility (Very Rare), Awareness (Rare), Fortitude (Very Rare), Greater Absorption (Legendary), Insight (Very Rare), Intellect (Very Rare), Leadership (Very Rare), Mastery (Legendary), Protection (Rare), Regeneration (Legendary), Reserve (Rare), Strength (Very Rare), Sustenance (Rare).', '{"item_type":"Wondrous Item","rarity":"Varies","requires_attunement":true,"attunement_condition":null,"properties":{"varies_by_type":true}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Iron Bands', 'iron-bands', null, 'This rusty iron sphere measures 3 inches in diameter and weighs 1 pound. You can take a Magic action to throw the sphere at a Huge or smaller creature you can see within 60 feet of yourself. Make a ranged attack roll. On a hit, the target has the Restrained condition. A creature that can touch the bands can take an action to make a DC 20 Strength (Athletics) check to break them.', '{"item_type":"Wondrous Item","rarity":"Rare","requires_attunement":false,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Iron Flask', 'iron-flask', null, 'While holding this brass-stoppered iron flask, you can take a Magic action to target a creature native to a plane of existence other than the one you''re on. If the flask is empty, the target must succeed on a DC 17 Wisdom saving throw or be trapped in the flask. Once trapped, a creature remains in the flask until released. You can release the creature, which then obeys your commands for 1 hour.', '{"item_type":"Wondrous Item","rarity":"Legendary","requires_attunement":false,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Javelin of Lightning', 'javelin-of-lightning', null, 'Each time you make an attack roll with this magic weapon and hit, you can have it deal Lightning damage instead of Piercing damage. Lightning Bolt. When you throw this weapon at a target no farther than 120 feet from you, you can forgo the attack roll and turn the weapon into a bolt of lightning dealing 4d6 Lightning damage (DC 13 Dexterity save for half). This property can''t be used again until the next dawn.', '{"item_type":"Weapon","rarity":"Uncommon","requires_attunement":false,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Lantern of Revealing', 'lantern-of-revealing', null, 'While lit, this hooded lantern burns for 6 hours on 1 pint of oil, shedding Bright Light in a 30-foot radius and Dim Light for an additional 30 feet. Invisible creatures and objects are visible as long as they are in the lantern''s Bright Light.', '{"item_type":"Wondrous Item","rarity":"Uncommon","requires_attunement":false,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Luck Blade', 'luck-blade', null, 'You gain a +1 bonus to attack rolls and damage rolls made with this magic weapon. While the weapon is on your person, you also gain a +1 bonus to saving throws. Luck. You can reroll one failed D20 Test per dawn. Wish. The weapon has 1d3 charges. While holding it, you can expend 1 charge and cast Wish from it.', '{"item_type":"Weapon","rarity":"Legendary","requires_attunement":true,"attunement_condition":null,"properties":{"bonus":1}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Mace of Disruption', 'mace-of-disruption', null, 'When you hit a Fiend or an Undead with this magic weapon, that creature takes an extra 2d6 Radiant damage. If the target has 25 Hit Points or fewer after taking this damage, it must succeed on a DC 15 Wisdom saving throw or be destroyed. On a successful save, the creature has the Frightened condition until the end of your next turn. While you hold this weapon, it sheds Bright Light in a 20-foot radius.', '{"item_type":"Weapon","rarity":"Rare","requires_attunement":true,"attunement_condition":null,"properties":{"extra_damage_vs_fiend_undead":"2d6 radiant"}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Mace of Smiting', 'mace-of-smiting', null, 'You gain a +1 bonus to attack rolls and damage rolls made with this magic weapon. The bonus increases to +3 when you use the weapon to attack a Construct. When you roll a 20 on an attack roll made with this weapon, the target takes an extra 7 Bludgeoning damage, or 14 Bludgeoning damage if it''s a Construct.', '{"item_type":"Weapon","rarity":"Rare","requires_attunement":false,"attunement_condition":null,"properties":{"bonus":1}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Mace of Terror', 'mace-of-terror', null, 'This magic weapon has 3 charges and regains 1d3 expended charges daily at dawn. While holding the weapon, you can take a Magic action and expend 1 charge to release a wave of terror. Each creature of your choice within 30 feet of you must succeed on a DC 15 Wisdom saving throw or have the Frightened condition for 1 minute.', '{"item_type":"Weapon","rarity":"Rare","requires_attunement":true,"attunement_condition":null,"properties":{"charges":3}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Mantle of Spell Resistance', 'mantle-of-spell-resistance', null, 'You have Advantage on saving throws against spells while you wear this cloak.', '{"item_type":"Wondrous Item","rarity":"Rare","requires_attunement":true,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Manual of Bodily Health', 'manual-of-bodily-health', null, 'This book contains health and nutrition tips, and its words are charged with magic. If you spend 48 hours over a period of 6 days or fewer studying the book''s contents and practicing its guidelines, your Constitution increases by 2, to a maximum of 30. The manual then loses its magic but regains it in a century.', '{"item_type":"Wondrous Item","rarity":"Very Rare","requires_attunement":false,"attunement_condition":null,"properties":{"stat_increase":"Constitution +2"}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Manual of Gainful Exercise', 'manual-of-gainful-exercise', null, 'This book describes fitness exercises, and its words are charged with magic. If you spend 48 hours over a period of 6 days or fewer studying the book''s contents and practicing its guidelines, your Strength increases by 2, to a maximum of 30. The manual then loses its magic but regains it in a century.', '{"item_type":"Wondrous Item","rarity":"Very Rare","requires_attunement":false,"attunement_condition":null,"properties":{"stat_increase":"Strength +2"}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Manual of Golems', 'manual-of-golems', null, 'This tome contains information and incantations necessary to make a particular type of golem. To decipher and use the manual, you must be a spellcaster with at least two level 5 spell slots. Types: Clay Golem (30 days, 65,000 GP), Flesh Golem (60 days, 50,000 GP), Iron Golem (120 days, 100,000 GP), Stone Golem (90 days, 80,000 GP).', '{"item_type":"Wondrous Item","rarity":"Very Rare","requires_attunement":false,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Manual of Quickness of Action', 'manual-of-quickness-of-action', null, 'This book contains coordination and balance exercises, and its words are charged with magic. If you spend 48 hours over a period of 6 days or fewer studying the book''s contents and practicing its guidelines, your Dexterity increases by 2, to a maximum of 30. The manual then loses its magic but regains it in a century.', '{"item_type":"Wondrous Item","rarity":"Very Rare","requires_attunement":false,"attunement_condition":null,"properties":{"stat_increase":"Dexterity +2"}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Marvelous Pigments', 'marvelous-pigments', null, 'This fine wooden box contains 1d4 pots of pigment and a brush. Using the brush and expending 1 pot of pigment, you can paint any number of three-dimensional objects and terrain features confined to a 20-foot Cube over 10 minutes. When the work is done, all the painted objects and terrain features become real. No object created by a pot of pigment can have a value greater than 25 GP.', '{"item_type":"Wondrous Item","rarity":"Very Rare","requires_attunement":false,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Medallion of Thoughts', 'medallion-of-thoughts', null, 'The medallion has 5 charges. While wearing it, you can expend 1 charge to cast Detect Thoughts (save DC 13) from it. The medallion regains 1d4 expended charges daily at dawn.', '{"item_type":"Wondrous Item","rarity":"Uncommon","requires_attunement":true,"attunement_condition":null,"properties":{"charges":5}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Mirror of Life Trapping', 'mirror-of-life-trapping', null, 'When this 4-foot-tall, 2-foot-wide mirror is viewed indirectly, its surface shows faint images of creatures. If the mirror is hanging on a vertical surface and you are within 5 feet of it, you can take a Magic action to activate it. Any creature other than you that sees its reflection in the activated mirror while within 30 feet must succeed on a DC 15 Charisma saving throw or be trapped in one of the mirror''s twelve extradimensional cells.', '{"item_type":"Wondrous Item","rarity":"Very Rare","requires_attunement":false,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Mithral Armor', 'mithral-armor', null, 'Mithral is a light, flexible metal. Armor made of this substance can be worn under normal clothes. If the armor normally imposes Disadvantage on Dexterity (Stealth) checks or has a Strength requirement, the mithral version of the armor doesn''t.', '{"item_type":"Armor","rarity":"Uncommon","requires_attunement":false,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Mysterious Deck', 'mysterious-deck', null, 'Usually found in a box or pouch, this deck contains a number of cards made of ivory or vellum. Most decks have thirteen cards, but some have twenty-two. Before you draw a card, you must declare how many cards you intend to draw. Each card drawn has a powerful effect including: Balance, Comet, Donjon, Euryale, Fates, Flames, Fool, Gem, Jester, Key, Knight, Moon, Puzzle, Rogue, Ruin, Sage, Skull, Star, Sun, Talons, Throne, and Void.', '{"item_type":"Wondrous Item","rarity":"Legendary","requires_attunement":false,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Necklace of Adaptation', 'necklace-of-adaptation', null, 'While wearing this necklace, you can breathe normally in any environment, and you have Advantage on saving throws made to avoid or end the Poisoned condition.', '{"item_type":"Wondrous Item","rarity":"Uncommon","requires_attunement":true,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Necklace of Fireballs', 'necklace-of-fireballs', null, 'This necklace has 1d6 + 3 beads hanging from it. You can take a Magic action to detach a bead and throw it up to 60 feet away. When it reaches the end of its trajectory, the bead detonates as a level 3 Fireball (save DC 15). You can hurl multiple beads at one time, increasing the damage by 1d6 for each bead after the first (maximum 12d6).', '{"item_type":"Wondrous Item","rarity":"Rare","requires_attunement":false,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Necklace of Prayer Beads', 'necklace-of-prayer-beads', null, 'This necklace has 1d4 + 2 magic beads. Six types of magic beads exist: Bead of Blessing (Bless), Bead of Curing (Cure Wounds level 2), Bead of Favor (Greater Restoration), Bead of Smiting (Shining Smite), Bead of Summons (Guardian of Faith), Bead of Wind Walking (Wind Walk). Each bead can be used once per dawn as a Bonus Action.', '{"item_type":"Wondrous Item","rarity":"Rare","requires_attunement":true,"attunement_condition":"by a Cleric, Druid, or Paladin","properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Nine Lives Stealer', 'nine-lives-stealer', null, 'You gain a +2 bonus to attack rolls and damage rolls made with this magic weapon. Life Stealing. The weapon has 1d8 + 1 charges. When you attack a creature that has fewer than 100 Hit Points with this weapon and roll a 20 on the d20 for the attack roll, the creature must succeed on a DC 15 Constitution saving throw or be slain instantly. The weapon loses 1 charge if the creature is slain.', '{"item_type":"Weapon","rarity":"Very Rare","requires_attunement":true,"attunement_condition":null,"properties":{"bonus":2}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Oathbow', 'oathbow', null, 'When you use this weapon to make a ranged attack, you can utter the command words to make the target your sworn enemy until it dies or until dawn 7 days later. When you make a ranged attack roll with this weapon against your sworn enemy, you have Advantage on the roll, your target gains no benefit from Half Cover or Three-Quarters Cover, and the attack deals an extra 3d6 Piercing damage.', '{"item_type":"Weapon","rarity":"Very Rare","requires_attunement":true,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Oil of Etherealness', 'oil-of-etherealness', null, 'One vial of this oil can cover one Medium or smaller creature. Applying the oil takes 10 minutes. The affected creature then gains the effect of the Etherealness spell for 1 hour. Beads of this cloudy, gray oil form on the outside of its container and quickly evaporate.', '{"item_type":"Potion","rarity":"Rare","requires_attunement":false,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Oil of Sharpness', 'oil-of-sharpness', null, 'One vial of this oil can coat one Melee weapon or twenty pieces of ammunition that deal Slashing or Piercing damage. Applying the oil takes 1 minute. The oil seeps into whatever it coats, turning the coated weapon into a +3 Weapon or the coated ammunition into +3 Ammunition.', '{"item_type":"Potion","rarity":"Very Rare","requires_attunement":false,"attunement_condition":null,"properties":{"bonus":3}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Oil of Slipperiness', 'oil-of-slipperiness', null, 'One vial of this oil can cover one Medium or smaller creature. Applying the oil takes 10 minutes. The affected creature then gains the effect of the Freedom of Movement spell for 8 hours. Alternatively, the oil can be poured on the ground as a Magic action to cover a 10-foot square, duplicating the effect of the Grease spell for 8 hours.', '{"item_type":"Potion","rarity":"Uncommon","requires_attunement":false,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Pearl of Power', 'pearl-of-power', null, 'While this pearl is on your person, you can take a Magic action to regain one expended spell slot of level 3 or lower. Once you use the pearl, it can''t be used again until the next dawn.', '{"item_type":"Wondrous Item","rarity":"Uncommon","requires_attunement":true,"attunement_condition":"by a Spellcaster","properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Periapt of Health', 'periapt-of-health', null, 'While wearing this pendant, you can take a Magic action to regain 2d4 + 2 Hit Points. Once used, this property can''t be used again until the next dawn. In addition, you have Advantage on saving throws to avoid or end the Poisoned condition while you wear this pendant.', '{"item_type":"Wondrous Item","rarity":"Uncommon","requires_attunement":true,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Periapt of Proof against Poison', 'periapt-of-proof-against-poison', null, 'This delicate silver chain has a brilliant-cut black gem pendant. While you wear it, you have Immunity to the Poisoned condition and Poison damage.', '{"item_type":"Wondrous Item","rarity":"Rare","requires_attunement":true,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Periapt of Wound Closure', 'periapt-of-wound-closure', null, 'While wearing this pendant, you gain the following benefits. Life Preservation: Whenever you make a Death Saving Throw, you can change a roll of 9 or lower to a 10. Natural Healing Boost: Whenever you roll a Hit Point Die to regain Hit Points, double the number of Hit Points it restores.', '{"item_type":"Wondrous Item","rarity":"Uncommon","requires_attunement":true,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Philter of Love', 'philter-of-love', null, 'The next time you see a creature within 10 minutes after drinking this philter, you are charmed by that creature and have the Charmed condition for 1 hour. This rose-hued, effervescent liquid contains one easy-to-miss bubble shaped like a heart.', '{"item_type":"Potion","rarity":"Uncommon","requires_attunement":false,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Pipes of Haunting', 'pipes-of-haunting', null, 'These pipes have 3 charges and regain 1d3 expended charges daily at dawn. You can take a Magic action to play them and expend 1 charge to create an eerie, spellbinding tune. Each creature of your choice within 30 feet of you must succeed on a DC 15 Wisdom saving throw or have the Frightened condition for 1 minute.', '{"item_type":"Wondrous Item","rarity":"Uncommon","requires_attunement":false,"attunement_condition":null,"properties":{"charges":3}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Pipes of the Sewers', 'pipes-of-the-sewers', null, 'While these pipes are on your person, ordinary rats and giant rats are Indifferent toward you and won''t attack you unless you threaten or harm them. The pipes have 3 charges and regain 1d3 expended charges daily at dawn. If you play the pipes as a Magic action, you can take a Bonus Action to expend 1 to 3 charges, calling forth one Swarm of Rats with each expended charge.', '{"item_type":"Wondrous Item","rarity":"Uncommon","requires_attunement":true,"attunement_condition":null,"properties":{"charges":3}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Plate Armor of Etherealness', 'plate-armor-of-etherealness', null, 'While you''re wearing this armor, you can take a Magic action and use a command word to gain the effect of the Etherealness spell. The spell ends immediately if you remove the armor or take a Magic action to repeat the command word. This property of the armor can''t be used again until the next dawn.', '{"item_type":"Armor","rarity":"Legendary","requires_attunement":true,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Portable Hole', 'portable-hole', null, 'This fine black cloth, soft as silk, unfolds into a circular sheet 6 feet in diameter. You can take a Magic action to place it on or against a solid surface, creating an extradimensional hole 10 feet deep. You can take a Magic action to close a Portable Hole by folding it up. Any creatures or objects within remain in the extradimensional space.', '{"item_type":"Wondrous Item","rarity":"Rare","requires_attunement":false,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Potion of Animal Friendship', 'potion-of-animal-friendship', null, 'When you drink this potion, you can cast the level 3 version of the Animal Friendship spell (save DC 13). Agitating this potion''s muddy liquid brings little bits into view: a fish scale, a hummingbird feather, a cat claw, or a squirrel hair.', '{"item_type":"Potion","rarity":"Uncommon","requires_attunement":false,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Potion of Clairvoyance', 'potion-of-clairvoyance', null, 'When you drink this potion, you gain the effect of the Clairvoyance spell (no Concentration required). An eyeball bobs in this potion''s yellowish liquid but vanishes when the potion is opened.', '{"item_type":"Potion","rarity":"Rare","requires_attunement":false,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Potion of Climbing', 'potion-of-climbing', null, 'When you drink this potion, you gain a Climb Speed equal to your Speed for 1 hour. During this time, you have Advantage on Strength (Athletics) checks to climb. This potion is separated into brown, silver, and gray layers resembling bands of stone.', '{"item_type":"Potion","rarity":"Common","requires_attunement":false,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Potion of Diminution', 'potion-of-diminution', null, 'When you drink this potion, you gain the "reduce" effect of the Enlarge/Reduce spell for 1d4 hours (no Concentration required). The red in the potion''s liquid continuously contracts to a tiny bead and then expands to color the clear liquid around it.', '{"item_type":"Potion","rarity":"Rare","requires_attunement":false,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Potion of Flying', 'potion-of-flying', null, 'When you drink this potion, you gain a Fly Speed equal to your Speed for 1 hour and can hover. If you''re in the air when the potion wears off, you fall unless you have some other means of staying aloft. This potion''s clear liquid floats at the top of its container.', '{"item_type":"Potion","rarity":"Very Rare","requires_attunement":false,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Potion of Gaseous Form', 'potion-of-gaseous-form', null, 'When you drink this potion, you gain the effect of the Gaseous Form spell for 1 hour (no Concentration required) or until you end the effect as a Bonus Action. This potion''s container seems to hold fog that moves and pours like water.', '{"item_type":"Potion","rarity":"Rare","requires_attunement":false,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Potion of Giant Strength', 'potion-of-giant-strength', null, 'When you drink this potion, your Strength score changes for 1 hour. The type of giant determines the score: Hill (21, Uncommon), Frost/Stone (23, Rare), Fire (25, Rare), Cloud (27, Very Rare), Storm (29, Legendary). The potion has no effect on you if your Strength is equal to or greater than that score.', '{"item_type":"Potion","rarity":"Varies","requires_attunement":false,"attunement_condition":null,"properties":{"varies_by_type":true}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Potion of Growth', 'potion-of-growth', null, 'When you drink this potion, you gain the "enlarge" effect of the Enlarge/Reduce spell for 10 minutes (no Concentration required). The red in the potion''s liquid continuously expands from a tiny bead to color the clear liquid around it and then contracts.', '{"item_type":"Potion","rarity":"Uncommon","requires_attunement":false,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Potion of Healing', 'potion-of-healing', null, 'You regain 2d4 + 2 Hit Points when you drink this potion. The potion''s red liquid glimmers when agitated.', '{"item_type":"Potion","rarity":"Common","requires_attunement":false,"attunement_condition":null,"properties":{"healing":"2d4+2"}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Potion of Healing (greater)', 'potion-of-healing-greater', null, 'You regain 4d4 + 4 Hit Points when you drink this potion. The potion''s red liquid glimmers when agitated.', '{"item_type":"Potion","rarity":"Uncommon","requires_attunement":false,"attunement_condition":null,"properties":{"healing":"4d4+4"}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Potion of Healing (superior)', 'potion-of-healing-superior', null, 'You regain 8d4 + 8 Hit Points when you drink this potion. The potion''s red liquid glimmers when agitated.', '{"item_type":"Potion","rarity":"Rare","requires_attunement":false,"attunement_condition":null,"properties":{"healing":"8d4+8"}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Potion of Healing (supreme)', 'potion-of-healing-supreme', null, 'You regain 10d4 + 20 Hit Points when you drink this potion. The potion''s red liquid glimmers when agitated.', '{"item_type":"Potion","rarity":"Very Rare","requires_attunement":false,"attunement_condition":null,"properties":{"healing":"10d4+20"}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Potion of Heroism', 'potion-of-heroism', null, 'When you drink this potion, you gain 10 Temporary Hit Points that last for 1 hour. For the same duration, you are under the effect of the Bless spell (no Concentration required). This potion''s blue liquid bubbles and steams as if boiling.', '{"item_type":"Potion","rarity":"Rare","requires_attunement":false,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Potion of Invisibility', 'potion-of-invisibility', null, 'This potion''s container looks empty but feels as though it holds liquid. When you drink the potion, you have the Invisible condition for 1 hour. The effect ends early if you make an attack roll, deal damage, or cast a spell.', '{"item_type":"Potion","rarity":"Rare","requires_attunement":false,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Potion of Invulnerability', 'potion-of-invulnerability', null, 'For 1 minute after you drink this potion, you have Resistance to all damage. This potion''s syrupy liquid looks like liquefied iron.', '{"item_type":"Potion","rarity":"Rare","requires_attunement":false,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Potion of Longevity', 'potion-of-longevity', null, 'When you drink this potion, your physical age is reduced by 1d6 + 6 years, to a minimum of 13 years. Each time you subsequently drink a Potion of Longevity, there is 10 percent cumulative chance that you instead age by 1d6 + 6 years.', '{"item_type":"Potion","rarity":"Very Rare","requires_attunement":false,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Potion of Mind Reading', 'potion-of-mind-reading', null, 'When you drink this potion, you gain the effect of the Detect Thoughts spell (save DC 13) for 10 minutes (no Concentration required). This potion''s dense, purple liquid has an ovoid cloud of pink floating in it.', '{"item_type":"Potion","rarity":"Rare","requires_attunement":false,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Potion of Poison', 'potion-of-poison', null, 'This concoction looks, smells, and tastes like a Potion of Healing or another beneficial potion. However, it is actually poison masked by illusion magic. If you drink this potion, you take 4d6 Poison damage and must succeed on a DC 13 Constitution saving throw or have the Poisoned condition for 1 hour.', '{"item_type":"Potion","rarity":"Uncommon","requires_attunement":false,"attunement_condition":null,"properties":{"cursed":true}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Potion of Resistance', 'potion-of-resistance', null, 'When you drink this potion, you have Resistance to one type of damage for 1 hour. The GM chooses the type or determines it randomly.', '{"item_type":"Potion","rarity":"Uncommon","requires_attunement":false,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Potion of Speed', 'potion-of-speed', null, 'When you drink this potion, you gain the effect of the Haste spell for 1 minute (no Concentration required) without suffering the wave of lethargy that typically occurs when the effect ends. This potion''s yellow fluid is streaked with black and swirls on its own.', '{"item_type":"Potion","rarity":"Very Rare","requires_attunement":false,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Potion of Vitality', 'potion-of-vitality', null, 'When you drink this potion, it removes any Exhaustion levels you have and ends the Poisoned condition on you. For the next 24 hours, you regain the maximum number of Hit Points for any Hit Point Die you spend.', '{"item_type":"Potion","rarity":"Very Rare","requires_attunement":false,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Potion of Water Breathing', 'potion-of-water-breathing', null, 'You can breathe underwater for 24 hours after drinking this potion. This potion''s cloudy green fluid smells of the sea and has a jellyfish-like bubble floating in it.', '{"item_type":"Potion","rarity":"Uncommon","requires_attunement":false,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Quarterstaff of the Acrobat', 'quarterstaff-of-the-acrobat', null, 'You have a +2 bonus to attack rolls and damage rolls made with this magic weapon. While holding this weapon, you can cause it to emit green Dim Light, alter its form between a 6-inch rod, a 10-foot pole, and a Quarterstaff. In Quarterstaff form: you have Advantage on Dexterity (Acrobatics) checks, can take a Reaction to gain +5 to AC against an attack, and the weapon has the Thrown property.', '{"item_type":"Weapon","rarity":"Very Rare","requires_attunement":true,"attunement_condition":null,"properties":{"bonus":2}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Ring of Animal Influence', 'ring-of-animal-influence', null, 'This ring has 3 charges, and it regains 1d3 expended charges daily at dawn. While wearing the ring, you can expend 1 charge to cast one of the following spells (save DC 13) from it: Animal Friendship, Fear (affects Beasts only), or Speak with Animals.', '{"item_type":"Ring","rarity":"Rare","requires_attunement":false,"attunement_condition":null,"properties":{"charges":3}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Ring of Djinni Summoning', 'ring-of-djinni-summoning', null, 'While wearing this ring, you can take a Magic action to summon a particular Djinni from the Elemental Plane of Air. The djinni appears in an unoccupied space within 120 feet of yourself. It remains as long as you maintain Concentration, to a maximum of 1 hour, or until it drops to 0 Hit Points. The ring becomes nonmagical if the djinni dies.', '{"item_type":"Ring","rarity":"Legendary","requires_attunement":true,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Ring of Elemental Command', 'ring-of-elemental-command', null, 'Each Ring of Elemental Command is linked to one of the four Elemental Planes. While wearing the ring, you have Advantage on attack rolls against Elementals and they have Disadvantage on attack rolls against you. You can also try to compel an Elemental (DC 18 Wisdom saving throw). Elemental Focus grants additional benefits based on the linked plane. The ring has 5 charges for casting plane-specific spells.', '{"item_type":"Ring","rarity":"Legendary","requires_attunement":true,"attunement_condition":null,"properties":{"charges":5}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Ring of Evasion', 'ring-of-evasion', null, 'This ring has 3 charges, and it regains 1d3 expended charges daily at dawn. When you fail a Dexterity saving throw while wearing the ring, you can take a Reaction to expend 1 charge to succeed on that save instead.', '{"item_type":"Ring","rarity":"Rare","requires_attunement":true,"attunement_condition":null,"properties":{"charges":3}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Ring of Feather Falling', 'ring-of-feather-falling', null, 'When you fall while wearing this ring, you descend 60 feet per round and take no damage from falling.', '{"item_type":"Ring","rarity":"Rare","requires_attunement":true,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Ring of Free Action', 'ring-of-free-action', null, 'While you wear this ring, Difficult Terrain doesn''t cost you extra movement. In addition, magic can neither reduce any of your Speeds nor cause you to have the Paralyzed or Restrained condition.', '{"item_type":"Ring","rarity":"Rare","requires_attunement":true,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Ring of Invisibility', 'ring-of-invisibility', null, 'While wearing this ring, you can take a Magic action to give yourself the Invisible condition. You remain Invisible until the ring is removed or until you take a Bonus Action to become visible again.', '{"item_type":"Ring","rarity":"Legendary","requires_attunement":true,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Ring of Jumping', 'ring-of-jumping', null, 'While wearing this ring, you can cast Jump from it, but can target only yourself when you do so.', '{"item_type":"Ring","rarity":"Uncommon","requires_attunement":true,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Ring of Mind Shielding', 'ring-of-mind-shielding', null, 'While wearing this ring, you are immune to magic that allows other creatures to read your thoughts, determine whether you are lying, know your alignment, or know your creature type. If you die while wearing the ring, your soul enters it. You can remain in the ring or depart for the afterlife.', '{"item_type":"Ring","rarity":"Uncommon","requires_attunement":true,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Ring of Protection', 'ring-of-protection', null, 'You gain a +1 bonus to Armor Class and saving throws while wearing this ring.', '{"item_type":"Ring","rarity":"Rare","requires_attunement":true,"attunement_condition":null,"properties":{"ac_bonus":1,"save_bonus":1}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Ring of Regeneration', 'ring-of-regeneration', null, 'While wearing this ring, you regain 1d6 Hit Points every 10 minutes if you have at least 1 Hit Point. If you lose a body part, the ring causes the missing part to regrow and return to full functionality after 1d6 + 1 days if you have at least 1 Hit Point the whole time.', '{"item_type":"Ring","rarity":"Very Rare","requires_attunement":true,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Ring of Resistance', 'ring-of-resistance', null, 'You have Resistance to one damage type while wearing this ring. The gemstone in the ring indicates the type: Pearl (Acid), Tourmaline (Cold), Garnet (Fire), Sapphire (Force), Citrine (Lightning), Jet (Necrotic), Amethyst (Poison), Jade (Psychic), Topaz (Radiant), Spinel (Thunder).', '{"item_type":"Ring","rarity":"Rare","requires_attunement":false,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Ring of Shooting Stars', 'ring-of-shooting-stars', null, 'You can cast Dancing Lights or Light from the ring. The ring has 6 charges and regains 1d6 expended charges daily at dawn. You can expend charges to use: Faerie Fire (1 charge), Lightning Spheres (2 charges, up to four 3-foot spheres), or Shooting Stars (1-3 charges to launch glowing motes dealing 5d4 Radiant damage in a 15-foot Cube).', '{"item_type":"Ring","rarity":"Very Rare","requires_attunement":true,"attunement_condition":null,"properties":{"charges":6}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Ring of Spell Storing', 'ring-of-spell-storing', null, 'This ring stores spells cast into it, holding them until the attuned wearer uses them. The ring can store up to 5 levels worth of spells at a time. Any creature can cast a spell of level 1 through 5 into the ring. While wearing this ring, you can cast any spell stored in it.', '{"item_type":"Ring","rarity":"Rare","requires_attunement":true,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Ring of Spell Turning', 'ring-of-spell-turning', null, 'While wearing this ring, you have Advantage on saving throws against spells. If you succeed on the save for a spell of level 7 or lower, the spell has no effect on you. If that spell targeted only you and didn''t create an area of effect, you can take a Reaction to deflect the spell back at the spell''s caster.', '{"item_type":"Ring","rarity":"Legendary","requires_attunement":true,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Ring of Swimming', 'ring-of-swimming', null, 'You have a Swim Speed of 40 feet while wearing this ring.', '{"item_type":"Ring","rarity":"Uncommon","requires_attunement":false,"attunement_condition":null,"properties":{"swim_speed":40}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Ring of Telekinesis', 'ring-of-telekinesis', null, 'While wearing this ring, you can cast Telekinesis from it.', '{"item_type":"Ring","rarity":"Very Rare","requires_attunement":true,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Ring of the Ram', 'ring-of-the-ram', null, 'This ring has 3 charges and regains 1d3 expended charges daily at dawn. While wearing the ring, you can take a Magic action to expend 1 to 3 charges to make a ranged spell attack against one creature within 60 feet. The ring produces a spectral ram''s head (+7 to hit). On a hit, for each charge you spend, the target takes 2d10 Force damage and is pushed 5 feet away.', '{"item_type":"Ring","rarity":"Rare","requires_attunement":true,"attunement_condition":null,"properties":{"charges":3}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Ring of Three Wishes', 'ring-of-three-wishes', null, 'While wearing this ring, you can expend 1 of its 3 charges to cast Wish from it. The ring becomes nonmagical when you use the last charge.', '{"item_type":"Ring","rarity":"Legendary","requires_attunement":false,"attunement_condition":null,"properties":{"charges":3}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Ring of Warmth', 'ring-of-warmth', null, 'If you take Cold damage while wearing this ring, the ring reduces the damage you take by 2d8. In addition, while wearing this ring, you and everything you wear and carry are unharmed by temperatures of 0 degrees Fahrenheit or lower.', '{"item_type":"Ring","rarity":"Uncommon","requires_attunement":true,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Ring of Water Walking', 'ring-of-water-walking', null, 'While wearing this ring, you cast Water Walk from it, targeting only yourself.', '{"item_type":"Ring","rarity":"Uncommon","requires_attunement":false,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Ring of X-ray Vision', 'ring-of-x-ray-vision', null, 'While wearing this ring, you can take a Magic action to gain X-ray vision with a range of 30 feet for 1 minute. The vision can penetrate 1 foot of stone, 1 inch of common metal, or up to 3 feet of wood or dirt. Whenever you use the ring again before taking a Long Rest, you must succeed on a DC 15 Constitution saving throw or gain 1 Exhaustion level.', '{"item_type":"Ring","rarity":"Rare","requires_attunement":true,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Robe of Eyes', 'robe-of-eyes', null, 'This robe is adorned with eyelike patterns. While you wear the robe, you gain All-Around Vision (Advantage on Perception checks relying on sight) and Special Senses (Darkvision and Truesight with a range of 120 feet). A Light spell or Daylight spell cast near the robe gives you the Blinded condition for 1 minute.', '{"item_type":"Wondrous Item","rarity":"Rare","requires_attunement":true,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Robe of Scintillating Colors', 'robe-of-scintillating-colors', null, 'This robe has 3 charges, and it regains 1d3 expended charges daily at dawn. While you wear it, you can take a Magic action and expend 1 charge to cause the garment to display a shifting pattern of dazzling hues until the end of your next turn. During this time, the robe sheds Bright Light in a 30-foot radius, creatures have Disadvantage on attack rolls against you, and creatures in the Bright Light must succeed on a DC 15 Wisdom saving throw or have the Stunned condition.', '{"item_type":"Wondrous Item","rarity":"Very Rare","requires_attunement":true,"attunement_condition":null,"properties":{"charges":3}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Robe of Stars', 'robe-of-stars', null, 'This black or dark-blue robe is embroidered with small white or silver stars. You gain a +1 bonus to saving throws while you wear it. Six large stars allow you to cast the level 5 version of Magic Missile (1d6 removed stars reappear at dusk). You can also take a Magic action to enter the Astral Plane while wearing the robe.', '{"item_type":"Wondrous Item","rarity":"Very Rare","requires_attunement":true,"attunement_condition":null,"properties":{"save_bonus":1}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Robe of the Archmagi', 'robe-of-the-archmagi', null, 'While wearing this robe, you gain: Armor (base AC 15 + Dexterity modifier if wearing no armor), Magic Resistance (Advantage on saving throws against spells and other magical effects), and War Mage (spell save DC and spell attack bonus each increase by 2).', '{"item_type":"Wondrous Item","rarity":"Legendary","requires_attunement":true,"attunement_condition":"by a Sorcerer, Warlock, or Wizard","properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Robe of Useful Items', 'robe-of-useful-items', null, 'This robe has cloth patches of various shapes and colors covering it. While wearing the robe, you can take a Magic action to detach one of the patches, causing it to become the object or creature it represents. The robe has two of each of the following patches: Bullseye Lantern, Dagger, Mirror, Pole, Rope (coiled), and Sack, plus 4d4 other randomly determined patches.', '{"item_type":"Wondrous Item","rarity":"Uncommon","requires_attunement":false,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Rod of Absorption', 'rod-of-absorption', null, 'While holding this rod, you can take a Reaction to absorb a spell that is targeting only you and doesn''t create an area of effect. The absorbed spell''s effect is canceled and its energy is stored in the rod (up to 50 levels total over its existence). If you are a spellcaster holding the rod, you can convert stored energy into spell slots.', '{"item_type":"Rod","rarity":"Very Rare","requires_attunement":true,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Rod of Alertness', 'rod-of-alertness', null, 'While holding the rod, you have Advantage on Wisdom (Perception) checks and on Initiative rolls. You can cast Detect Evil and Good, Detect Magic, Detect Poison and Disease, and See Invisibility from it. You can also plant the rod in the ground to shed Bright Light in a 60-foot radius and grant a +1 bonus to AC and saving throws to allies in the light.', '{"item_type":"Rod","rarity":"Very Rare","requires_attunement":true,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Rod of Lordly Might', 'rod-of-lordly-might', null, 'This rod functions as a magic Mace that grants a +3 bonus to attack rolls and damage rolls. Six buttons allow it to transform: into a flaming Longsword or Shortsword (+2d6 Fire damage), a Battleaxe, a Spear, a climbing pole, a battering ram, or a compass. It also has Drain Life, Paralyze, and Terrify properties.', '{"item_type":"Rod","rarity":"Legendary","requires_attunement":true,"attunement_condition":null,"properties":{"bonus":3}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Rod of Resurrection', 'rod-of-resurrection', null, 'The rod has 5 charges. While you hold it, you can cast Heal (1 charge) or Resurrection (5 charges) from it. The rod regains 1 expended charge daily at dawn. If you expend the last charge, roll 1d20. On a 1, the rod disappears in a harmless burst of radiance.', '{"item_type":"Rod","rarity":"Legendary","requires_attunement":true,"attunement_condition":null,"properties":{"charges":5}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Rod of Rulership', 'rod-of-rulership', null, 'You can take a Magic action to present the rod and command obedience from each creature of your choice that you can see within 120 feet. Each target must succeed on a DC 15 Wisdom saving throw or have the Charmed condition for 8 hours. Once used, this property can''t be used again until the next dawn.', '{"item_type":"Rod","rarity":"Rare","requires_attunement":true,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Rod of Security', 'rod-of-security', null, 'While holding this rod, you can take a Magic action to activate it. The rod then instantly transports you and up to 199 other willing creatures you can see to a demiplane of your design. The demiplane contains enough water and food to sustain its visitors. Visitors can remain there for up to 200 days divided by the number of creatures present.', '{"item_type":"Rod","rarity":"Very Rare","requires_attunement":false,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Rope of Climbing', 'rope-of-climbing', null, 'This 60-foot length of rope can hold up to 3,000 pounds. While holding one end of the rope, you can take a Magic action to command the other end to animate and move toward a destination you choose. You can also tell the rope to fasten itself to an object, knot or unknot itself, or coil itself for carrying. The rope has AC 20, HP 20, and Immunity to Poison and Psychic damage.', '{"item_type":"Wondrous Item","rarity":"Uncommon","requires_attunement":false,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Rope of Entanglement', 'rope-of-entanglement', null, 'This rope is 30 feet long. While holding one end, you can take a Magic action to command the other end to dart forward and entangle one creature you can see within 20 feet. The target must succeed on a DC 15 Dexterity saving throw or have the Restrained condition. The rope has AC 20, HP 20, and Immunity to Poison and Psychic damage.', '{"item_type":"Wondrous Item","rarity":"Rare","requires_attunement":false,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Scarab of Protection', 'scarab-of-protection', null, 'This beetle-shaped medallion provides three benefits: Defense (+1 bonus to Armor Class), Preservation (12 charges; if you fail a saving throw against a Necromancy spell or harmful effect from an Undead, you can expend 1 charge to turn the failed save into a successful one), and Spell Resistance (Advantage on saving throws against spells).', '{"item_type":"Wondrous Item","rarity":"Legendary","requires_attunement":true,"attunement_condition":null,"properties":{"charges":12,"ac_bonus":1}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Scimitar of Speed', 'scimitar-of-speed', null, 'You gain a +2 bonus to attack rolls and damage rolls made with this magic weapon. In addition, you can make one attack with it as a Bonus Action on each of your turns.', '{"item_type":"Weapon","rarity":"Very Rare","requires_attunement":true,"attunement_condition":null,"properties":{"bonus":2}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Sending Stones', 'sending-stones', null, 'Sending Stones come in pairs, with each stone carved to match the other. While you touch one stone, you can cast Sending from it. The target is the bearer of the other stone. Once Sending is cast using either stone, the stones can''t be used again until the next dawn.', '{"item_type":"Wondrous Item","rarity":"Uncommon","requires_attunement":false,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Sentinel Shield', 'sentinel-shield', null, 'While holding this Shield, you have Advantage on Initiative rolls and Wisdom (Perception) checks. The Shield is emblazoned with a symbol of an eye.', '{"item_type":"Armor","rarity":"Uncommon","requires_attunement":false,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Shield, +1', 'shield-1', null, 'While holding this Shield, you have a +1 bonus to Armor Class in addition to the Shield''s normal bonus to AC.', '{"item_type":"Armor","rarity":"Uncommon","requires_attunement":false,"attunement_condition":null,"properties":{"bonus":1}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Shield, +2', 'shield-2', null, 'While holding this Shield, you have a +2 bonus to Armor Class in addition to the Shield''s normal bonus to AC.', '{"item_type":"Armor","rarity":"Rare","requires_attunement":false,"attunement_condition":null,"properties":{"bonus":2}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Shield, +3', 'shield-3', null, 'While holding this Shield, you have a +3 bonus to Armor Class in addition to the Shield''s normal bonus to AC.', '{"item_type":"Armor","rarity":"Very Rare","requires_attunement":false,"attunement_condition":null,"properties":{"bonus":3}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Shield of Missile Attraction', 'shield-of-missile-attraction', null, 'While holding this Shield, you have Resistance to damage from attacks made with Ranged weapons. Curse. Attuning to it curses you until you are targeted by a Remove Curse spell. Whenever an attack with a Ranged weapon targets a creature within 10 feet of you, the curse causes you to become the target instead.', '{"item_type":"Armor","rarity":"Rare","requires_attunement":true,"attunement_condition":null,"properties":{"cursed":true}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Shield of the Cavalier', 'shield-of-the-cavalier', null, 'While holding this Shield, you have a +2 bonus to Armor Class in addition to the Shield''s normal bonus to AC. Forceful Bash: When you take the Attack action, you can make one attack with the Shield dealing 2d6 + 2 + Strength modifier Force damage. Protective Field: As a Reaction, you can create an immobile 5-foot Emanation that protects creatures inside it for up to 1 minute.', '{"item_type":"Armor","rarity":"Very Rare","requires_attunement":true,"attunement_condition":null,"properties":{"ac_bonus":2}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Slippers of Spider Climbing', 'slippers-of-spider-climbing', null, 'While you wear these light shoes, you can move up, down, and across vertical surfaces and along ceilings, while leaving your hands free. You have a Climb Speed equal to your Speed. However, the slippers don''t allow you to move this way on a slippery surface, such as one covered by ice or oil.', '{"item_type":"Wondrous Item","rarity":"Uncommon","requires_attunement":true,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Sovereign Glue', 'sovereign-glue', null, 'This viscous, milky-white substance can form a permanent adhesive bond between any two objects. One ounce of the glue can cover a 1-foot square surface. Once the glue sets after 1 minute, the bond it creates can be broken only by the application of Universal Solvent or Oil of Etherealness, or with a Wish spell.', '{"item_type":"Wondrous Item","rarity":"Legendary","requires_attunement":false,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Spell Scroll', 'spell-scroll', null, 'A Spell Scroll bears the words of a single spell. If the spell is on your spell list, you can read the scroll and cast its spell without Material components. Cantrip/Level 1 (Common), Level 2-3 (Uncommon), Level 4-5 (Rare), Level 6-8 (Very Rare), Level 9 (Legendary). Once the spell is cast, the scroll crumbles to dust.', '{"item_type":"Scroll","rarity":"Varies","requires_attunement":false,"attunement_condition":null,"properties":{"varies_by_type":true}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Spellguard Shield', 'spellguard-shield', null, 'While holding this Shield, you have Advantage on saving throws against spells and other magical effects, and spell attack rolls have Disadvantage against you.', '{"item_type":"Armor","rarity":"Very Rare","requires_attunement":true,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Sphere of Annihilation', 'sphere-of-annihilation', null, 'This 2-foot-diameter black sphere is a hole in the multiverse, hovering in space and stabilized by a magical field surrounding it. The sphere obliterates all matter it passes through and all matter that passes through it. Artifacts are the exception. If you are within 60 feet of a sphere, you can take a Magic action to make a DC 25 Intelligence (Arcana) check to control it.', '{"item_type":"Wondrous Item","rarity":"Legendary","requires_attunement":false,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Staff of Charming', 'staff-of-charming', null, 'This staff has 10 charges. While holding the staff, you can use its properties: cast Charm Person, Command, or Comprehend Languages (1 charge each); if you succeed on a saving throw against an Enchantment spell, you can Reflect Enchantment (1 charge); if you fail, you can Resist Enchantment (once per dawn). The staff regains 1d8 + 2 expended charges daily at dawn.', '{"item_type":"Staff","rarity":"Rare","requires_attunement":true,"attunement_condition":"by a Bard, Cleric, Druid, Sorcerer, Warlock, or Wizard","properties":{"charges":10}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Staff of Fire', 'staff-of-fire', null, 'You have Resistance to Fire damage while you hold this staff. The staff has 10 charges for casting Burning Hands (1 charge), Fireball (3 charges), or Wall of Fire (4 charges). The staff regains 1d6 + 4 expended charges daily at dawn.', '{"item_type":"Staff","rarity":"Very Rare","requires_attunement":true,"attunement_condition":"by a Druid, Sorcerer, Warlock, or Wizard","properties":{"charges":10}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Staff of Frost', 'staff-of-frost', null, 'You have Resistance to Cold damage while you hold this staff. The staff has 10 charges for casting Fog Cloud (1 charge), Ice Storm (4 charges), Cone of Cold (5 charges), or Wall of Ice (4 charges). The staff regains 1d6 + 4 expended charges daily at dawn.', '{"item_type":"Staff","rarity":"Very Rare","requires_attunement":true,"attunement_condition":"by a Druid, Sorcerer, Warlock, or Wizard","properties":{"charges":10}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Staff of Healing', 'staff-of-healing', null, 'This staff has 10 charges for casting Cure Wounds (1 charge per spell level, max 4), Lesser Restoration (2 charges), or Mass Cure Wounds (5 charges). The staff regains 1d6 + 4 expended charges daily at dawn.', '{"item_type":"Staff","rarity":"Rare","requires_attunement":true,"attunement_condition":"by a Bard, Cleric, or Druid","properties":{"charges":10}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Staff of Power', 'staff-of-power', null, 'This staff has 20 charges and can be wielded as a magic Quarterstaff that grants a +2 bonus to attack rolls and damage rolls. While holding it, you gain a +2 bonus to Armor Class, saving throws, and spell attack rolls. You can cast various spells from it. The staff can also be broken in a Retributive Strike.', '{"item_type":"Staff","rarity":"Very Rare","requires_attunement":true,"attunement_condition":"by a Sorcerer, Warlock, or Wizard","properties":{"bonus":2,"charges":20}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Staff of Striking', 'staff-of-striking', null, 'This staff can be wielded as a magic Quarterstaff that grants a +3 bonus to attack rolls and damage rolls. The staff has 10 charges. When you hit with a melee attack using it, you can expend up to 3 charges. For each charge you expend, the target takes an extra 1d6 Force damage.', '{"item_type":"Staff","rarity":"Very Rare","requires_attunement":true,"attunement_condition":null,"properties":{"bonus":3,"charges":10}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Staff of Swarming Insects', 'staff-of-swarming-insects', null, 'This staff has 10 charges. Insect Cloud: While holding the staff, you can expend 1 charge to cause a swarm of harmless flying insects to fill a 30-foot Emanation for 10 minutes. You can also cast Giant Insect (4 charges) or Insect Plague (5 charges). The staff regains 1d6 + 4 expended charges daily at dawn.', '{"item_type":"Staff","rarity":"Rare","requires_attunement":true,"attunement_condition":"by a Bard, Cleric, Druid, Sorcerer, Warlock, or Wizard","properties":{"charges":10}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Staff of the Magi', 'staff-of-the-magi', null, 'This staff has 50 charges and can be wielded as a magic Quarterstaff that grants a +2 bonus to attack rolls and damage rolls. While holding it, you have Advantage on saving throws against spells and can absorb spells that target only you (gaining charges equal to the spell''s level). You can cast a wide variety of spells from it. The staff can also be used in a Retributive Strike.', '{"item_type":"Staff","rarity":"Legendary","requires_attunement":true,"attunement_condition":"by a Sorcerer, Warlock, or Wizard","properties":{"bonus":2,"charges":50}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Staff of the Python', 'staff-of-the-python', null, 'As a Magic action, you can throw this staff so that it lands in an unoccupied space within 10 feet of you, causing the staff to become a Giant Constrictor Snake in that space under your control. As a Bonus Action, you can command the snake to revert to staff form; you can''t use the staff''s property again for 1 hour. If the snake is reduced to 0 Hit Points, the staff is destroyed.', '{"item_type":"Staff","rarity":"Uncommon","requires_attunement":true,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Staff of the Woodlands', 'staff-of-the-woodlands', null, 'This staff has 6 charges and can be wielded as a magic Quarterstaff that grants a +2 bonus to attack rolls and damage rolls. While holding it, you have a +2 bonus to spell attack rolls. You can cast spells from it (Animal Friendship, Awaken, Barkskin, Locate Animals or Plants, Pass without Trace, Speak with Animals, Speak with Plants, Wall of Thorns) and transform it into a tree.', '{"item_type":"Staff","rarity":"Rare","requires_attunement":true,"attunement_condition":"by a Druid","properties":{"bonus":2,"charges":6}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Staff of Thunder and Lightning', 'staff-of-thunder-and-lightning', null, 'This staff can be wielded as a magic Quarterstaff that grants a +2 bonus to attack rolls and damage rolls. It also has additional properties (each usable once per dawn): Lightning (extra 2d6 Lightning damage on hit), Thunder (target makes DC 17 Constitution save or Stunned), Thunder and Lightning (combined use), Lightning Strike (120-foot Line dealing 9d6 Lightning), and Thunderclap (60-foot Emanation dealing 2d6 Thunder, DC 17).', '{"item_type":"Staff","rarity":"Very Rare","requires_attunement":true,"attunement_condition":null,"properties":{"bonus":2}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Staff of Withering', 'staff-of-withering', null, 'This staff has 3 charges and regains 1d3 expended charges daily at dawn. The staff can be wielded as a magic Quarterstaff. On a hit, you can expend 1 charge to deal an extra 2d10 Necrotic damage and force the target to make a DC 15 Constitution saving throw. On a failed save, the target has Disadvantage for 1 hour on any ability check or saving throw that uses Strength or Constitution.', '{"item_type":"Staff","rarity":"Rare","requires_attunement":true,"attunement_condition":null,"properties":{"charges":3}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Stone of Controlling Earth Elementals', 'stone-of-controlling-earth-elementals', null, 'While touching this 5-pound stone to the ground, you can take a Magic action to summon an Earth Elemental. The elemental obeys your commands and takes its turn immediately after you on your Initiative count. The elemental disappears after 1 hour, when it dies, or when you dismiss it as a Bonus Action. The stone can''t be used this way again until the next dawn.', '{"item_type":"Wondrous Item","rarity":"Rare","requires_attunement":false,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Stone of Good Luck', 'stone-of-good-luck', null, 'While this polished agate is on your person, you gain a +1 bonus to ability checks and saving throws.', '{"item_type":"Wondrous Item","rarity":"Uncommon","requires_attunement":true,"attunement_condition":null,"properties":{"save_bonus":1,"ability_check_bonus":1}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Sun Blade', 'sun-blade', null, 'This item appears to be a sword hilt. While grasping the hilt, you can take a Bonus Action to cause a blade of pure radiance to spring into existence. This magic weapon functions as a Longsword with the Finesse property. You gain a +2 bonus to attack rolls and damage rolls, which deals Radiant damage. When you hit an Undead with it, that target takes an extra 1d8 Radiant damage. The blade emits Bright Light in a 15-foot radius.', '{"item_type":"Weapon","rarity":"Rare","requires_attunement":true,"attunement_condition":null,"properties":{"bonus":2}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Sword of Life Stealing', 'sword-of-life-stealing', null, 'When you attack a creature with this magic weapon and roll a 20 on the d20 for the attack roll, that target takes an extra 15 Necrotic damage if it isn''t a Construct or an Undead, and you gain Temporary Hit Points equal to the amount of Necrotic damage taken.', '{"item_type":"Weapon","rarity":"Rare","requires_attunement":true,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Sword of Sharpness', 'sword-of-sharpness', null, 'When you attack an object with this magic weapon and hit, maximize your weapon damage dice against the target. When you attack a creature with this weapon and roll a 20 on the d20 for the attack roll, that target takes an extra 14 Slashing damage and gains 1 Exhaustion level.', '{"item_type":"Weapon","rarity":"Very Rare","requires_attunement":true,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Sword of Wounding', 'sword-of-wounding', null, 'When you hit a creature with an attack using this magic weapon, the target takes an extra 2d6 Necrotic damage and must succeed on a DC 15 Constitution saving throw or be unable to regain Hit Points for 1 hour. The target repeats the save at the end of each of its turns, ending the effect on itself on a success.', '{"item_type":"Weapon","rarity":"Rare","requires_attunement":true,"attunement_condition":null,"properties":{"extra_damage":"2d6 necrotic"}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Talisman of Pure Good', 'talisman-of-pure-good', null, 'This item symbolizes pure goodness. A Fiend or an Undead that touches the talisman takes 8d6 Radiant damage. You can use the talisman as a Holy Symbol gaining a +2 bonus to spell attack rolls. The talisman has 7 charges; you can expend 1 charge to target a creature on the ground within 120 feet, opening a flaming fissure (DC 20 Dexterity save or destroyed).', '{"item_type":"Wondrous Item","rarity":"Legendary","requires_attunement":true,"attunement_condition":"by a Cleric or Paladin","properties":{"charges":7}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Talisman of the Sphere', 'talisman-of-the-sphere', null, 'While holding or wearing this talisman, you have Advantage on any Intelligence (Arcana) check you make to control a Sphere of Annihilation. In addition, when you start your turn in control of a Sphere of Annihilation, you can take a Magic action to move it 10 feet plus 10 times your Intelligence modifier.', '{"item_type":"Wondrous Item","rarity":"Legendary","requires_attunement":true,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Talisman of Ultimate Evil', 'talisman-of-ultimate-evil', null, 'This item symbolizes unrepentant evil. A creature that isn''t a Fiend or an Undead that touches the talisman takes 8d6 Necrotic damage. You can use the talisman as a Holy Symbol gaining a +2 bonus to spell attack rolls. The talisman has 6 charges; you can expend 1 charge to target a creature on the ground within 120 feet, opening a flaming fissure (DC 20 Dexterity save or destroyed).', '{"item_type":"Wondrous Item","rarity":"Legendary","requires_attunement":true,"attunement_condition":null,"properties":{"charges":6}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Thunderous Greatclub', 'thunderous-greatclub', null, 'While you are attuned to this magic weapon, your Strength is 20 unless your Strength is already equal to or greater than that score. The weapon deals an extra 1d8 Thunder damage to any creature it hits. Clap of Thunder (Magic action): creates a 30-foot Cone dealing Thunder damage (DC 15 Strength save). Earthquake (Magic action): 50-foot-radius circle affecting structures and creatures (DC 20 Dexterity save).', '{"item_type":"Weapon","rarity":"Very Rare","requires_attunement":true,"attunement_condition":null,"properties":{"strength":20}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Tome of Clear Thought', 'tome-of-clear-thought', null, 'This book contains memory and logic exercises, and its words are charged with magic. If you spend 48 hours over a period of 6 days or fewer studying the book''s contents and practicing its guidelines, your Intelligence increases by 2, to a maximum of 30. The manual then loses its magic but regains it in a century.', '{"item_type":"Wondrous Item","rarity":"Very Rare","requires_attunement":false,"attunement_condition":null,"properties":{"stat_increase":"Intelligence +2"}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Tome of Leadership and Influence', 'tome-of-leadership-and-influence', null, 'This book contains guidelines for influencing and charming others, and its words are charged with magic. If you spend 48 hours over a period of 6 days or fewer studying the book''s contents and practicing its guidelines, your Charisma increases by 2, to a maximum of 30. The manual then loses its magic but regains it in a century.', '{"item_type":"Wondrous Item","rarity":"Very Rare","requires_attunement":false,"attunement_condition":null,"properties":{"stat_increase":"Charisma +2"}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Tome of Understanding', 'tome-of-understanding', null, 'This book contains intuition and insight exercises, and its words are charged with magic. If you spend 48 hours over a period of 6 days or fewer studying the book''s contents and practicing its guidelines, your Wisdom increases by 2, to a maximum of 30. The manual then loses its magic, but regains it in a century.', '{"item_type":"Wondrous Item","rarity":"Very Rare","requires_attunement":false,"attunement_condition":null,"properties":{"stat_increase":"Wisdom +2"}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Trident of Fish Command', 'trident-of-fish-command', null, 'This magic weapon has 3 charges, and it regains 1d3 expended charges daily at dawn. While you carry it, you can expend 1 charge to cast Dominate Beast (save DC 15) from it on a Beast that has a Swim Speed.', '{"item_type":"Weapon","rarity":"Uncommon","requires_attunement":true,"attunement_condition":null,"properties":{"charges":3}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Universal Solvent', 'universal-solvent', null, 'This tube holds milky liquid with a strong alcohol smell. When found, a tube contains 1d6 + 1 ounces. You can take a Utilize action to pour 1 or more ounces of solvent from the tube onto a surface within reach. Each ounce instantly dissolves up to 1 square foot of adhesive it touches, including Sovereign Glue.', '{"item_type":"Wondrous Item","rarity":"Legendary","requires_attunement":false,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Vicious Weapon', 'vicious-weapon', null, 'This magic weapon deals an extra 2d6 damage to any creature it hits. This extra damage is of the same type as the weapon''s normal damage.', '{"item_type":"Weapon","rarity":"Rare","requires_attunement":false,"attunement_condition":null,"properties":{"extra_damage":"2d6"}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Vorpal Sword', 'vorpal-sword', null, 'You gain a +3 bonus to attack rolls and damage rolls made with this magic weapon. In addition, the weapon ignores Resistance to Slashing damage. When you use this weapon to attack a creature that has at least one head and roll a 20 on the d20 for the attack roll, you cut off one of the creature''s heads. The creature dies if it can''t survive without the lost head.', '{"item_type":"Weapon","rarity":"Legendary","requires_attunement":true,"attunement_condition":null,"properties":{"bonus":3}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Wand of Binding', 'wand-of-binding', null, 'This wand has 7 charges. While holding the wand, you can cast Hold Monster (5 charges) or Hold Person (2 charges) (save DC 17). The wand regains 1d6 + 1 expended charges daily at dawn.', '{"item_type":"Wand","rarity":"Rare","requires_attunement":true,"attunement_condition":null,"properties":{"charges":7}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Wand of Enemy Detection', 'wand-of-enemy-detection', null, 'This wand has 7 charges. While holding it, you can take a Magic action to expend 1 charge. For 1 minute, you know the direction of the nearest creature Hostile to you within 60 feet, but not its distance. The wand regains 1d6 + 1 expended charges daily at dawn.', '{"item_type":"Wand","rarity":"Rare","requires_attunement":true,"attunement_condition":null,"properties":{"charges":7}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Wand of Fear', 'wand-of-fear', null, 'This wand has 7 charges. While holding the wand, you can cast Command ("flee" or "grovel" only, 1 charge) or Fear in a 60-foot Cone (3 charges) (save DC 15). The wand regains 1d6 + 1 expended charges daily at dawn.', '{"item_type":"Wand","rarity":"Rare","requires_attunement":true,"attunement_condition":null,"properties":{"charges":7}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Wand of Fireballs', 'wand-of-fireballs', null, 'This wand has 7 charges. While holding it, you can expend no more than 3 charges to cast Fireball (save DC 15) from it. For 1 charge, you cast the level 3 version of the spell. You can increase the spell''s level by 1 for each additional charge you expend. The wand regains 1d6 + 1 expended charges daily at dawn.', '{"item_type":"Wand","rarity":"Rare","requires_attunement":true,"attunement_condition":"by a Spellcaster","properties":{"charges":7}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Wand of Lightning Bolts', 'wand-of-lightning-bolts', null, 'This wand has 7 charges. While holding it, you can expend no more than 3 charges to cast Lightning Bolt (save DC 15) from it. For 1 charge, you cast the level 3 version of the spell. You can increase the spell''s level by 1 for each additional charge you expend. The wand regains 1d6 + 1 expended charges daily at dawn.', '{"item_type":"Wand","rarity":"Rare","requires_attunement":true,"attunement_condition":"by a Spellcaster","properties":{"charges":7}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Wand of Magic Detection', 'wand-of-magic-detection', null, 'This wand has 3 charges. While holding it, you can expend 1 charge to cast Detect Magic from it. The wand regains 1d3 expended charges daily at dawn.', '{"item_type":"Wand","rarity":"Uncommon","requires_attunement":false,"attunement_condition":null,"properties":{"charges":3}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Wand of Magic Missiles', 'wand-of-magic-missiles', null, 'This wand has 7 charges. While holding it, you can expend no more than 3 charges to cast Magic Missile from it. For 1 charge, you cast the level 1 version of the spell. You can increase the spell''s level by 1 for each additional charge you expend. The wand regains 1d6 + 1 expended charges daily at dawn.', '{"item_type":"Wand","rarity":"Uncommon","requires_attunement":false,"attunement_condition":null,"properties":{"charges":7}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Wand of Paralysis', 'wand-of-paralysis', null, 'This wand has 7 charges. While holding it, you can take a Magic action to expend 1 charge to cause a thin blue ray to streak toward a creature you can see within 60 feet. The target must succeed on a DC 15 Constitution saving throw or have the Paralyzed condition for 1 minute. The wand regains 1d6 + 1 expended charges daily at dawn.', '{"item_type":"Wand","rarity":"Rare","requires_attunement":true,"attunement_condition":"by a Spellcaster","properties":{"charges":7}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Wand of Polymorph', 'wand-of-polymorph', null, 'This wand has 7 charges. While holding it, you can expend 1 charge to cast Polymorph (save DC 15) from it. The wand regains 1d6 + 1 expended charges daily at dawn.', '{"item_type":"Wand","rarity":"Very Rare","requires_attunement":true,"attunement_condition":"by a Spellcaster","properties":{"charges":7}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Wand of Secrets', 'wand-of-secrets', null, 'This wand has 3 charges and regains 1d3 expended charges daily at dawn. While holding it, you can take a Magic action to expend 1 charge, and if a secret door or trap is within 60 feet of you, the wand pulses and points at the one nearest to you.', '{"item_type":"Wand","rarity":"Uncommon","requires_attunement":false,"attunement_condition":null,"properties":{"charges":3}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Wand of the War Mage, +1', 'wand-of-the-war-mage-1', null, 'While holding this wand, you gain a +1 bonus to spell attack rolls determined by the wand''s rarity. In addition, you ignore Half Cover when making a spell attack roll.', '{"item_type":"Wand","rarity":"Uncommon","requires_attunement":true,"attunement_condition":"by a Spellcaster","properties":{"bonus":1}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Wand of the War Mage, +2', 'wand-of-the-war-mage-2', null, 'While holding this wand, you gain a +2 bonus to spell attack rolls. In addition, you ignore Half Cover when making a spell attack roll.', '{"item_type":"Wand","rarity":"Rare","requires_attunement":true,"attunement_condition":"by a Spellcaster","properties":{"bonus":2}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Wand of the War Mage, +3', 'wand-of-the-war-mage-3', null, 'While holding this wand, you gain a +3 bonus to spell attack rolls. In addition, you ignore Half Cover when making a spell attack roll.', '{"item_type":"Wand","rarity":"Very Rare","requires_attunement":true,"attunement_condition":"by a Spellcaster","properties":{"bonus":3}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Wand of Web', 'wand-of-web', null, 'This wand has 7 charges. While holding it, you can expend 1 charge to cast Web (save DC 13) from it. The wand regains 1d6 + 1 expended charges daily at dawn.', '{"item_type":"Wand","rarity":"Uncommon","requires_attunement":true,"attunement_condition":"by a Spellcaster","properties":{"charges":7}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Wand of Wonder', 'wand-of-wonder', null, 'This wand has 7 charges. While holding it, you can take a Magic action to expend 1 charge while choosing a point within 120 feet of yourself. That location becomes the point of origin of a spell or other magical effect determined by rolling on the Wand of Wonder Effects table (1d100). Spells cast from the wand have a save DC of 15. The wand regains 1d6 + 1 expended charges daily at dawn.', '{"item_type":"Wand","rarity":"Rare","requires_attunement":true,"attunement_condition":null,"properties":{"charges":7}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Weapon, +1', 'weapon-1', null, 'You have a +1 bonus to attack rolls and damage rolls made with this magic weapon.', '{"item_type":"Weapon","rarity":"Uncommon","requires_attunement":false,"attunement_condition":null,"properties":{"bonus":1}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Weapon, +2', 'weapon-2', null, 'You have a +2 bonus to attack rolls and damage rolls made with this magic weapon.', '{"item_type":"Weapon","rarity":"Rare","requires_attunement":false,"attunement_condition":null,"properties":{"bonus":2}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Weapon, +3', 'weapon-3', null, 'You have a +3 bonus to attack rolls and damage rolls made with this magic weapon.', '{"item_type":"Weapon","rarity":"Very Rare","requires_attunement":false,"attunement_condition":null,"properties":{"bonus":3}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Weapon of Warning', 'weapon-of-warning', null, 'As long as this weapon is within your reach and you are attuned to it, you and allies within 30 feet of you gain: Alarm (the weapon magically awakens sleeping subjects when combat begins) and Supernatural Readiness (each subject has Advantage on Initiative rolls).', '{"item_type":"Weapon","rarity":"Uncommon","requires_attunement":true,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Well of Many Worlds', 'well-of-many-worlds', null, 'This fine black cloth, soft as silk, unfolds into a circular sheet 6 feet in diameter. You can take a Magic action to unfold the Well of Many Worlds and place it on a solid surface, whereupon it forms a two-way, 6-foot-diameter, circular portal to another world or plane of existence. The portal remains open until a creature within 5 feet of it takes a Magic action to close it. Once opened, it can''t open again for 1d8 hours.', '{"item_type":"Wondrous Item","rarity":"Legendary","requires_attunement":false,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Wind Fan', 'wind-fan', null, 'While holding this fan, you can cast Gust of Wind (save DC 13) from it. Each subsequent time the fan is used before the next dawn, it has a cumulative 20 percent chance of not working; if the fan fails to work, it tears into useless, nonmagical tatters.', '{"item_type":"Wondrous Item","rarity":"Uncommon","requires_attunement":false,"attunement_condition":null,"properties":{}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Winged Boots', 'winged-boots', null, 'These boots have 4 charges and regain 1d4 expended charges daily at dawn. While wearing the boots, you can take a Magic action to expend 1 charge, gaining a Fly Speed of 30 feet for 1 hour. If you are flying when the duration expires, you descend at a rate of 30 feet per round until you land.', '{"item_type":"Wondrous Item","rarity":"Uncommon","requires_attunement":true,"attunement_condition":null,"properties":{"charges":4,"fly_speed":30}}'::jsonb, null),
  ('dnd5e-2024', 'magic_item', 'Wings of Flying', 'wings-of-flying', null, 'While wearing this cloak, you can take a Magic action to turn the cloak into a pair of wings on your back. The wings last for 1 hour or until you end the effect early as a Magic action. The wings give you a Fly Speed of 60 feet. If you are aloft when the wings disappear, you fall. When the wings disappear, you can''t use them again for 1d12 hours.', '{"item_type":"Wondrous Item","rarity":"Rare","requires_attunement":true,"attunement_condition":null,"properties":{"fly_speed":60}}'::jsonb, null)
on conflict do nothing;

-- dnd5e-2024 / species (9)
insert into public.content (system_id, kind, name, slug, summary, description, data, parent_id) values
  ('dnd5e-2024', 'species', 'Dragonborn', 'dragonborn', null, null, '{"speed":30,"traits":{"traits":[{"name":"Draconic Ancestry","description":"Your lineage stems from a dragon progenitor. Choose a dragon type (Black, Blue, Brass, Bronze, Copper, Gold, Green, Red, Silver, or White). This determines your Breath Weapon damage type and Damage Resistance."},{"name":"Breath Weapon","description":"When you take the Attack action, you can replace one attack with a 15-foot Cone or 30-foot Line (5 feet wide) breath. Each creature makes a Dexterity save (DC = 8 + Constitution modifier + Proficiency Bonus). Fail: 1d10 damage of your ancestry type; Success: half. Scales: 2d10 at level 5, 3d10 at level 11, 4d10 at level 17. Uses equal to Proficiency Bonus; recharge on Long Rest."},{"name":"Damage Resistance","description":"You have Resistance to the damage type determined by your Draconic Ancestry."},{"name":"Darkvision","description":"You have Darkvision with a range of 60 feet."},{"name":"Draconic Flight","description":"Starting at character level 5, as a Bonus Action you sprout spectral wings for 10 minutes, gaining a Fly Speed equal to your Speed. Once per Long Rest."}]},"ability_score_bonuses":{},"size":"Medium","creature_type":"Humanoid"}'::jsonb, null),
  ('dnd5e-2024', 'species', 'Dwarf', 'dwarf', null, null, '{"speed":30,"traits":{"traits":[{"name":"Darkvision","description":"You have Darkvision with a range of 120 feet."},{"name":"Dwarven Resilience","description":"You have Resistance to Poison damage and Advantage on saving throws to avoid or end the Poisoned condition."},{"name":"Dwarven Toughness","description":"Your Hit Point maximum increases by 1, and it increases by 1 again whenever you gain a level."},{"name":"Stonecunning","description":"As a Bonus Action, you gain Tremorsense with a range of 60 feet for 10 minutes while on or touching a stone surface. Uses equal to Proficiency Bonus; recharge on Long Rest."}]},"ability_score_bonuses":{},"size":"Medium","creature_type":"Humanoid"}'::jsonb, null),
  ('dnd5e-2024', 'species', 'Elf', 'elf', null, null, '{"speed":30,"traits":{"traits":[{"name":"Darkvision","description":"You have Darkvision with a range of 60 feet (Drow lineage extends this to 120 feet)."},{"name":"Elven Lineage","description":"Choose a lineage: Drow (Darkvision 120 ft, Dancing Lights cantrip; Faerie Fire at level 3; Darkness at level 5), High Elf (Prestidigitation cantrip, swap each Long Rest; Detect Magic at level 3; Misty Step at level 5), or Wood Elf (Speed 35, Druidcraft cantrip; Longstrider at level 3; Pass without Trace at level 5). Spell DC uses your chosen INT, WIS, or CHA."},{"name":"Fey Ancestry","description":"You have Advantage on saving throws to avoid or end the Charmed condition."},{"name":"Keen Senses","description":"You have proficiency in the Insight, Perception, or Survival skill (your choice)."},{"name":"Trance","description":"You don''t need to sleep and magic can''t put you to sleep. You can finish a Long Rest in 4 hours of trancelike meditation."}]},"ability_score_bonuses":{},"size":"Medium","creature_type":"Humanoid"}'::jsonb, null),
  ('dnd5e-2024', 'species', 'Gnome', 'gnome', null, null, '{"speed":30,"traits":{"traits":[{"name":"Darkvision","description":"You have Darkvision with a range of 60 feet."},{"name":"Gnomish Cunning","description":"You have Advantage on Intelligence, Wisdom, and Charisma saving throws."},{"name":"Gnomish Lineage","description":"Choose a lineage. Forest Gnome: Minor Illusion cantrip + Speak with Animals (always prepared, cast without slot equal to Proficiency Bonus times per Long Rest). Rock Gnome: Mending and Prestidigitation cantrips + can craft a Tiny clockwork device (AC 5, 1 HP) with 10 min casting; up to 3 devices exist at once, falling apart after 8 hours. Spell DC uses your chosen INT, WIS, or CHA."}]},"ability_score_bonuses":{},"size":"Small","creature_type":"Humanoid"}'::jsonb, null),
  ('dnd5e-2024', 'species', 'Goliath', 'goliath', null, null, '{"speed":35,"traits":{"traits":[{"name":"Giant Ancestry","description":"Choose one supernatural benefit (uses equal to Proficiency Bonus; recharge Long Rest): Cloud''s Jaunt — teleport 30 ft as Bonus Action; Fire''s Burn — deal +1d10 Fire damage on a hit; Frost''s Chill — deal +1d6 Cold damage on a hit and reduce Speed by 10 ft until your next turn; Hill''s Tumble — give Prone condition to a Large or smaller creature on a hit; Stone''s Endurance — Reaction to roll 1d12 + CON modifier and reduce incoming damage by that total; Storm''s Thunder — Reaction to deal 1d8 Thunder to a creature within 60 ft that damaged you."},{"name":"Large Form","description":"Starting at character level 5, as a Bonus Action you change your size to Large for 10 minutes (if space allows), gaining Advantage on Strength checks and +10 ft Speed. Once per Long Rest."},{"name":"Powerful Build","description":"You have Advantage on checks to end the Grappled condition and count as one size larger for carrying capacity."}]},"ability_score_bonuses":{},"size":"Medium","creature_type":"Humanoid"}'::jsonb, null),
  ('dnd5e-2024', 'species', 'Halfling', 'halfling', null, null, '{"speed":30,"traits":{"traits":[{"name":"Brave","description":"You have Advantage on saving throws to avoid or end the Frightened condition."},{"name":"Halfling Nimbleness","description":"You can move through the space of any creature that is a size larger than you, but can''t stop in the same space."},{"name":"Luck","description":"When you roll a 1 on the d20 of a D20 Test, you can reroll the die and must use the new roll."},{"name":"Naturally Stealthy","description":"You can take the Hide action even when obscured only by a creature that is at least one size larger than you."}]},"ability_score_bonuses":{},"size":"Small","creature_type":"Humanoid"}'::jsonb, null),
  ('dnd5e-2024', 'species', 'Human', 'human', null, null, '{"speed":30,"traits":{"traits":[{"name":"Resourceful","description":"You gain Heroic Inspiration whenever you finish a Long Rest."},{"name":"Skillful","description":"You gain proficiency in one skill of your choice."},{"name":"Versatile","description":"You gain an Origin feat of your choice. Skilled is recommended."}],"size_note":"Choose Medium (about 4-7 feet tall) or Small (about 2-4 feet tall) when you select this species."},"ability_score_bonuses":{},"size":"Medium or Small","creature_type":"Humanoid"}'::jsonb, null),
  ('dnd5e-2024', 'species', 'Orc', 'orc', null, null, '{"speed":30,"traits":{"traits":[{"name":"Adrenaline Rush","description":"You can take the Dash action as a Bonus Action, gaining Temporary Hit Points equal to your Proficiency Bonus. Uses equal to Proficiency Bonus; recharge on Short or Long Rest."},{"name":"Darkvision","description":"You have Darkvision with a range of 120 feet."},{"name":"Relentless Endurance","description":"When reduced to 0 Hit Points but not killed outright, you can drop to 1 Hit Point instead. Once per Long Rest."}]},"ability_score_bonuses":{},"size":"Medium","creature_type":"Humanoid"}'::jsonb, null),
  ('dnd5e-2024', 'species', 'Tiefling', 'tiefling', null, null, '{"speed":30,"traits":{"traits":[{"name":"Darkvision","description":"You have Darkvision with a range of 60 feet."},{"name":"Fiendish Legacy","description":"Choose a legacy: Abyssal (Poison Resistance; Poison Spray cantrip; Ray of Sickness at level 3; Hold Person at level 5), Chthonic (Necrotic Resistance; Chill Touch cantrip; False Life at level 3; Ray of Enfeeblement at level 5), or Infernal (Fire Resistance; Fire Bolt cantrip; Hellish Rebuke at level 3; Darkness at level 5). Spell DC uses your chosen INT, WIS, or CHA."},{"name":"Otherworldly Presence","description":"You know the Thaumaturgy cantrip, using the same spellcasting ability as your Fiendish Legacy trait."}],"size_note":"Choose Medium (about 4-7 feet tall) or Small (about 3-4 feet tall) when you select this species."},"ability_score_bonuses":{},"size":"Medium or Small","creature_type":"Humanoid"}'::jsonb, null)
on conflict do nothing;

-- dnd5e-2024 / spell (339)
insert into public.content (system_id, kind, name, slug, summary, description, data, parent_id) values
  ('dnd5e-2024', 'spell', 'Acid Arrow', 'acid-arrow', null, 'A shimmering green arrow streaks toward a target
within range and bursts in a spray of acid. Make a
ranged spell attack against the target. On a hit, the
target takes 4d4 Acid damage and 2d4 Acid dam-
age at the end of its next turn. On a miss, the arrow
splashes the target with acid for half as much of the
initial damage only.
Using a Higher-Level Spell Slot. The damage
(both initial and later) increases by 1d4 for each
spell slot level above 2.', '{"level":2,"school":"Evocation","casting_time":"Action","range":"90 feet","components":"V, S, M (powdered rhubarb leaf)","duration":"Instantaneous","classes":["wizard"],"is_ritual":false,"requires_concentration":false}'::jsonb, null),
  ('dnd5e-2024', 'spell', 'Acid Splash', 'acid-splash', null, 'You create an acidic bubble at a point within range,
where it explodes in a 5-foot-radius Sphere. Each
creature in that Sphere must succeed on a Dexterity
saving throw or take 1d6 Acid damage.
Cantrip Upgrade. The damage increases by 1d6
when you reach levels 5 (2d6), 11 (3d6), and 17
(4d6).', '{"level":0,"school":"Evocation","casting_time":"Action","range":"60 feet","components":"V, S","duration":"Instantaneous","classes":["sorcerer","wizard"],"is_ritual":false,"requires_concentration":false}'::jsonb, null),
  ('dnd5e-2024', 'spell', 'Aid', 'aid', null, 'Choose up to three creatures within range. Each
target''s Hit Point maximum and current Hit Points
increase by 5 for the duration.
Using a Higher-Level Spell Slot. Each target''s Hit
Points increase by 5 for each spell slot level above 2.', '{"level":2,"school":"Abjuration","casting_time":"Action","range":"30 feet","components":"V, S, M (a strip of white cloth)","duration":"8 hours","classes":["bard","cleric","druid","paladin","ranger"],"is_ritual":false,"requires_concentration":false}'::jsonb, null),
  ('dnd5e-2024', 'spell', 'Alarm', 'alarm', null, 'You set an alarm against intrusion. Choose a door,
a window, or an area within range that is no larger
than a 20-foot Cube. Until the spell ends, an alarm
alerts you whenever a creature touches or enters
the warded area. When you cast the spell, you can
designate creatures that won''t set off the alarm. You
also choose whether the alarm is audible or mental:
Audible Alarm. The alarm produces the sound of
a handbell for 10 seconds within 60 feet of the
warded area.
Mental Alarm. You are alerted by a mental ping
if you are within 1 mile of the warded area. This
ping awakens you if you''re asleep.', '{"level":1,"school":"Abjuration","casting_time":"1 minute","range":"30 feet","components":"V, S, M (a bell and silver wire)","duration":"8 hours","classes":["ranger","wizard"],"is_ritual":true,"requires_concentration":false}'::jsonb, null),
  ('dnd5e-2024', 'spell', 'Alter Self', 'alter-self', null, 'You alter your physical form. Choose one of the
following options. Its effects last for the duration,
during which you can take a Magic action to replace
the option you chose with a different one.
Aquatic Adaptation. You sprout gills and grow
webs between your fingers. You can breathe under-
water and gain a Swim Speed equal to your Speed.
Change Appearance. You alter your appear-
ance. You decide what you look like, including your
height, weight, facial features, sound of your voice,
hair length, coloration, and other distinguishing
characteristics. You can make yourself appear as
a member of another species, though none of your
statistics change. You can''t appear as a creature of a
different size, and your basic shape stays the same;
if you''re bipedal, you can''t use this spell to become
quadrupedal, for instance. For the duration, you can
take a Magic action to change your appearance in
this way again.
Natural Weapons. You grow claws (Slashing),
fangs (Piercing), horns (Piercing), or hooves (Blud-
geoning). When you use your Unarmed Strike to
deal damage with that new growth, it deals 1d6
damage of the type in parentheses instead of deal-
ing the normal damage for your Unarmed Strike,
and you use your spellcasting ability modifier
for the attack and damage rolls rather than using
Strength.', '{"level":2,"school":"Transmutation","casting_time":"Action","range":"Self","components":"V, S","duration":"Concentration, up to 1 hour","classes":["sorcerer","wizard"],"is_ritual":false,"requires_concentration":true}'::jsonb, null),
  ('dnd5e-2024', 'spell', 'Animal Friendship', 'animal-friendship', null, 'Target a Beast that you can see within range. The
target must succeed on a Wisdom saving throw or
have the Charmed condition for the duration. If you
or one of your allies deals damage to the target, the
spells ends.
Using a Higher-Level Spell Slot. You can target
one additional Beast for each spell slot level above 1.', '{"level":1,"school":"Enchantment","casting_time":"Action","range":"30 feet","components":"V, S, M (a morsel of food)","duration":"24 hours","classes":["bard","druid","ranger"],"is_ritual":false,"requires_concentration":false}'::jsonb, null),
  ('dnd5e-2024', 'spell', 'Animal Messenger', 'animal-messenger', null, 'A Tiny Beast of your choice that you can see within
range must succeed on a Charisma saving throw,
or it attempts to deliver a message for you (if the
target''s Challenge Rating isn''t 0, it automatically
succeeds). You specify a location you have visited
and a recipient who matches a general descrip-
tion, such as "a person dressed in the uniform of
the town guard" or "a red-haired dwarf wearing a
pointed hat." You also communicate a message of
up to twenty-five words. The Beast travels for the
duration toward the specified location, covering
about 25 miles per 24 hours or 50 miles if the Beast
can fly.
When the Beast arrives, it delivers your message
to the creature that you described, mimicking your
communication. If the Beast doesn''t reach its desti-
nation before the spell ends, the message is lost, and
the Beast returns to where you cast the spell.
Using a Higher-Level Spell Slot. The spell''s dura-
tion increases by 48 hours for each spell slot level
above 2.', '{"level":2,"school":"Enchantment","casting_time":"Action","range":"30 feet","components":"V, S, M (a morsel of food)","duration":"24 hours","classes":["bard","druid","ranger"],"is_ritual":true,"requires_concentration":false}'::jsonb, null),
  ('dnd5e-2024', 'spell', 'Animal Shapes', 'animal-shapes', null, 'Choose any number of willing creatures that you
can see within range. Each target shape-shifts into
a Large or smaller Beast of your choice that has a
Challenge Rating of 4 or lower. You can choose a dif-
ferent form for each target. On later turns, you can
take a Magic action to transform the targets again.
A target''s game statistics are replaced by the
chosen Beast''s statistics, but the target retains its
creature type; Hit Points; Hit Point Dice; alignment;
ability to communicate; and Intelligence, Wisdom,
and Charisma scores. The target''s actions are lim-
ited by the Beast form''s anatomy, and it can''t cast
spells. The target''s equipment melds into the new
form, and the target can''t use any of that equipment
while in that form.
The target gains a number of Temporary Hit
Points equal to the Hit Points of the first form into
which it shape-shifts. These Temporary Hit Points
vanish if any remain when the spell ends. The trans-
formation lasts for the duration or until the target
ends it as a Bonus Action.', '{"level":8,"school":"Transmutation","casting_time":"Action","range":"30 feet","components":"V, S","duration":"24 hours","classes":["druid"],"is_ritual":false,"requires_concentration":false}'::jsonb, null),
  ('dnd5e-2024', 'spell', 'Animate Dead', 'animate-dead', null, 'Choose a pile of bones or a corpse of a Medium or
Small Humanoid within range. The target becomes
an Undead creature: a Skeleton if you chose bones
or a Zombie if you chose a corpse (see "Monsters"
for the stat blocks).
On each of your turns, you can take a Bonus Ac-
tion to mentally command any creature you made
with this spell if the creature is within 60 feet of
you (if you control multiple creatures, you can
command any of them at the same time, issuing the
same command to each one). You decide what action
the creature will take and where it will move on
its next turn, or you can issue a general command,
such as to guard a chamber or corridor. If you issue
no commands, the creature takes the Dodge action
and moves only to avoid harm. Once given an order,
the creature continues to follow it until its task is
complete.
The creature is under your control for 24 hours,
after which it stops obeying any command you''ve
given it. To maintain control of the creature for an-
other 24 hours, you must cast this spell on the crea-
ture again before the current 24-hour period ends.
This use of the spell reasserts your control over up
to four creatures you have animated with this spell
rather than animating a new creature.
Using a Higher-Level Spell Slot. You animate or
reassert control over two additional Undead crea-
tures for each spell slot level above 3. Each of the
creatures must come from a different corpse or pile
of bones.', '{"level":3,"school":"Necromancy","casting_time":"1 minute","range":"10 feet","components":"V, S, M (a drop of blood, a piece of flesh, and a pinch of bone dust)","duration":"Instantaneous","classes":["cleric","wizard"],"is_ritual":false,"requires_concentration":false}'::jsonb, null),
  ('dnd5e-2024', 'spell', 'Animate Objects', 'animate-objects', null, 'Objects animate at your command. Choose a num-
ber of nonmagical objects within range that aren''t
being worn or carried, aren''t fixed to a surface, and
aren''t Gargantuan. The maximum number of objects
is equal to your spellcasting ability modifier; for
this number, a Medium or smaller target counts as
one object, a Large target counts as two, and a Huge
target counts as three.
Each target animates, sprouts legs, and becomes
a Construct that uses the Animated Object stat
block; this creature is under your control until the
spell ends or until it is reduced to 0 Hit Points. Each
creature you make with this spell is an ally to you
and your allies. In combat, it shares your Initiative
count and takes its turn immediately after yours.
Until the spell ends, you can take a Bonus Action
to mentally command any creature you made with
this spell if the creature is within 500 feet of you (if
you control multiple creatures, you can command
any of them at the same time, issuing the same
command to each one). If you issue no commands,
the creature takes the Dodge action and moves only
to avoid harm. When the creature drops to 0 Hit
Points, it reverts to its object form, and any remain-
ing damage carries over to that form.
Using a Higher-Level Spell Slot. The creature''s
Slam damage increases by 1d4 (Medium or smaller),
1d6 (Large), or 1d12 (Huge) for each spell slot level
above 5.
or make attacks with Ranged or Reach weapons
through the barrier.
If you move so that an affected creature is forced
to pass through the barrier, the spell ends.', '{"level":5,"school":"Transmutation","casting_time":"Action","range":"120 feet","components":"V, S","duration":"Concentration, up to 1 minute","classes":["bard","sorcerer","wizard"],"is_ritual":false,"requires_concentration":true}'::jsonb, null),
  ('dnd5e-2024', 'spell', 'Antilife Shell', 'antilife-shell', null, 'An aura extends from you in a 10-foot Emanation
for the duration. The aura prevents creatures other
than Constructs and Undead from passing or reach-
ing through it. An affected creature can cast spells
Wisdom saving throw to end the effect, as de-
scribed below.
Ending the Effect. If the Frightened or Charmed
creature ends its turn more than 120 feet away
from the target, the creature makes a Wisdom sav-
ing throw. On a successful save, the creature is no
longer affected by the target. A creature that suc-
cessfully saves against this effect is immune to it for
1 minute, after which it can be affected again.', '{"level":5,"school":"Abjuration","casting_time":"Action","range":"Self","components":"V, S","duration":"Concentration, up to 1 hour","classes":["druid"],"is_ritual":false,"requires_concentration":true}'::jsonb, null),
  ('dnd5e-2024', 'spell', 'Antimagic Field', 'antimagic-field', null, 'An aura of antimagic surrounds you in 10-foot Em-
anation. No one can cast spells, take Magic actions,
or create other magical effects inside the aura, and
those things can''t target or otherwise affect any-
thing inside it. Magical properties of magic items
don''t work inside the aura or on anything inside it.
Areas of effect created by spells or other magic
can''t extend into the aura, and no one can teleport
into or out of it or use planar travel there. Portals
close temporarily while in the aura.
Ongoing spells, except those cast by an Artifact or
a deity, are suppressed in the area. While an effect
is suppressed, it doesn''t function, but the time it
spends suppressed counts against its duration.
Dispel Magic has no effect on the aura, and the au-
ras created by different Antimagic Field spells don''t
nullify each other.', '{"level":8,"school":"Abjuration","casting_time":"Action","range":"Self","components":"V, S, M (iron filings)","duration":"Concentration, up to 1 hour","classes":["cleric","wizard"],"is_ritual":false,"requires_concentration":true}'::jsonb, null),
  ('dnd5e-2024', 'spell', 'Antipathy/Sympathy', 'antipathy-sympathy', null, 'As you cast the spell, choose whether it creates
antipathy or sympathy, and target one creature or
object that is Huge or smaller. Then specify a kind of
creature, such as red dragons, goblins, or vampires.
