(4d10).', '{"level":0,"school":"Evocation","casting_time":"Action","range":"120 feet","components":"V, S","duration":"Instantaneous","classes":["sorcerer","wizard"],"is_ritual":false,"requires_concentration":false}'::jsonb, null),
  ('dnd5e-2024', 'spell', 'Fire Shield', 'fire-shield', null, 'Wispy flames wreathe your body for the duration,
shedding Bright Light in a 10-foot radius and Dim
Light for an additional 10 feet.
The flames provide you with a warm shield or a
chill shield, as you choose. The warm shield grants
