  ('dnd5e-2024', 'spell', 'Healing Word', 'healing-word', null, 'A creature of your choice that you can see within
range regains Hit Points equal to 2d4 plus your
spellcasting ability modifier.
Using a Higher-Level Spell Slot. The healing in-
creases by 2d4 for each spell slot level above 1.', '{"level":1,"school":"Abjuration","casting_time":"Bonus Action","range":"60 feet","components":"V","duration":"Instantaneous","classes":["bard","cleric","druid"],"is_ritual":false,"requires_concentration":false}'::jsonb, null),
  ('dnd5e-2024', 'spell', 'Heat Metal', 'heat-metal', null, 'Choose a manufactured metal object, such as a
metal weapon or a suit of Heavy or Medium metal
armor, that you can see within range. You cause
the object to glow red-hot. Any creature in physical
contact with the object takes 2d8 Fire damage when
